    ytUrl: 'https://www.youtube.com/playlist?list=PLlpPf-YgbU7Gssxi9f72cZktgOb4Vpdoy',
    icon: '🔥',
  },
];

export default function DreamingSpanishSection({
  currentDay,
  onCompleteMission,
}: DreamingSpanishSectionProps) {
  const phase = currentDay <= 30 ? 1 : currentDay <= 60 ? 2 : 3;
  const defaultId = phase === 1 ? 'superbeginner' : phase === 2 ? 'beginner' : 'intermediate';

  const [selectedId, setSelectedId] = useState(defaultId);
  const [secondsLeft, setSecondsLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [completed, setCompleted] = useState(false);

  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;
    if (isActive && secondsLeft > 0) {
      interval = setInterval(() => setSecondsLeft((s) => s - 1), 1000);
    } else if (secondsLeft === 0 && isActive) {
      setIsActive(false);
      setCompleted(true);
      soundEngine.playVictoryFanfare();
      try { confetti({ particleCount: 120, spread: 80 }); } catch { /* ignore */ }
      if (onCompleteMission) onCompleteMission();
    }
    return () => { if (interval) clearInterval(interval); };
  }, [isActive, secondsLeft, onCompleteMission]);

  const formatTime = (s: number) =>
    `${Math.floor(s / 60).toString().padStart(2, '0')}:${(s % 60).toString().padStart(2, '0')}`;

  const active = DS_LEVELS.find((l) => l.id === selectedId) || DS_LEVELS[0];

  const handleOpenYouTube = () => {
    if (!isActive && !completed) {
      setIsActive(true);
      soundEngine.playTick();
    }
    window.open(active.ytUrl, '_blank', 'noopener,noreferrer');
  };

  return (
    <div className="apple-glass p-8 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <span className="apple-pill-badge bg-[var(--accent-cyan)]/15 text-[var(--accent-cyan)] border border-[var(--accent-cyan)]/30 mb-2">
            Comprehensible Input · Den {currentDay}
          </span>
          <h2 className="apple-heading-md text-[var(--text-primary)] flex items-center gap-2">
            🎧 Dreaming Spanish
          </h2>
          <p className="text-xs text-[var(--text-secondary)] mt-1">
            Sleduj 25 minut · vnímej z kontextu · <span className="text-[var(--accent-cyan)] font-semibold">bez slovníku</span>
          </p>
        </div>

        {/* Timer */}
        <div className="flex items-center gap-3 bg-[var(--card-bg)] px-5 py-3 rounded-2xl border border-[var(--card-border)] self-start sm:self-auto">
          <span className={`text-3xl font-black font-mono tabular-nums ${completed ? 'text-[var(--accent-emerald)]' : isActive ? 'text-[var(--accent-amber)]' : 'text-[var(--accent-cyan)]'}`}>
            {formatTime(secondsLeft)}
          </span>
          {secondsLeft < 25 * 60 && !completed && (
            <button
              onClick={() => { setIsActive(!isActive); isActive ? soundEngine.playUntick() : soundEngine.playTick(); }}
              className={`px-4 py-2 rounded-full font-bold text-xs transition cursor-pointer ${
                isActive
                  ? 'bg-[var(--accent-amber)] text-black'
                  : 'bg-[var(--card-bg-hover)] text-[var(--text-primary)] border border-[var(--card-border)]'
              }`}
            >
              {isActive ? '⏸ Pauza' : '▶ Pokračovat'}
            </button>
          )}
          {secondsLeft < 25 * 60 && !completed && (
            <button
              onClick={() => { setIsActive(false); setSecondsLeft(25 * 60); }}
              className="text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)] cursor-pointer transition"
            >
              Reset
            </button>
          )}
          {completed && (
            <span className="text-xs font-bold text-[var(--accent-emerald)]">✓ Hotovo!</span>
          )}
        </div>
      </div>

      {/* Level tabs */}
      <div className="flex gap-2 flex-wrap">
        {DS_LEVELS.map((lvl) => {
          const isSel = lvl.id === selectedId;
          return (
            <button
              key={lvl.id}
              onClick={() => { soundEngine.playTick(); setSelectedId(lvl.id); }}
              className={`px-4 py-2.5 rounded-full border text-xs font-bold transition cursor-pointer flex items-center gap-2 ${
                isSel
                  ? 'bg-[var(--accent-cyan)]/15 border-[var(--accent-cyan)] text-[var(--accent-cyan)] shadow-sm'
                  : 'bg-[var(--card-bg)] border-[var(--card-border)] text-[var(--text-secondary)] hover:bg-[var(--card-bg-hover)] hover:text-[var(--text-primary)]'
              }`}
            >
              <span>{lvl.icon}</span>
              <span>{lvl.label}</span>
              <span className={`text-[10px] font-mono px-2 py-0.5 rounded-full ${isSel ? 'bg-[var(--accent-cyan)]/20 text-[var(--accent-cyan)]' : 'bg-[var(--card-border)] text-[var(--text-muted)]'}`}>
                {lvl.phase}
              </span>
            </button>
          );
        })}
      </div>

      {/* Selected level card + CTA */}
      <div className="bg-[var(--card-bg)] border border-[var(--card-border)] rounded-2xl p-6 flex flex-col sm:flex-row items-start sm:items-center gap-6">
        <div className="flex-1 space-y-1.5">
          <div className="flex items-center gap-2">
            <span className="text-2xl">{active.icon}</span>
            <span className="font-extrabold text-[var(--text-primary)] text-lg">DS {active.label}</span>
            <span className="text-[10px] text-[var(--accent-cyan)] font-mono bg-[var(--accent-cyan)]/10 px-2.5 py-0.5 rounded-full border border-[var(--accent-cyan)]/20">{active.days}</span>
          </div>
          <p className="text-xs text-[var(--text-secondary)] leading-relaxed">{active.desc}</p>
        </div>

        <a
          href={active.ytUrl}
          target="_blank"
          rel="noopener noreferrer"
          onClick={handleOpenYouTube}
          className="shrink-0 flex items-center gap-2.5 px-6 py-3.5 bg-red-600 hover:bg-red-500 text-white font-extrabold text-xs rounded-full transition hover:scale-105 active:scale-95 shadow-lg cursor-pointer whitespace-nowrap"
        >
          <svg className="w-5 h-5" viewBox="0 0 24 24" fill="currentColor">
            <path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.6 12 3.6 12 3.6s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/>
          </svg>
          Sledovat na YouTube ↗
        </a>
      </div>

      <p className="text-[11px] text-[var(--text-muted)] text-center">
        💡 Kliknutím na tlačítko výše se spustí 25min časovač a otevře playlist na YouTube — sleduj a vrať se potvrdit misi!
      </p>

      {completed && (
        <div className="bg-[var(--accent-emerald)]/10 border border-[var(--accent-emerald)]/30 p-4 rounded-2xl text-sm text-[var(--accent-emerald)] font-bold flex items-center gap-2">
          🎉 25 minut splněno! <span className="font-normal opacity-80">(+15 bodů připsáno)</span>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { IslandCategory, IslandSentence } from '@/lib/data/islands-parser';
import { saveCustomIslandToStorage } from '@/lib/firebase/db';

interface CustomIslandModalProps {
  userId: string;
  isOpen: boolean;
  onClose: () => void;
  onSaved: (newCategory: IslandCategory) => void;
}

const ICONS = ['🏝️', '✈️', '🍕', '💼', '🚗', '⚽', '🎵', '🛍️', '🏥', '💬'];

export default function CustomIslandModal({
  userId,
  isOpen,
  onClose,
  onSaved,
}: CustomIslandModalProps) {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [difficulty, setDifficulty] = useState<'A1' | 'A2' | 'B1'>('A1');
  const [icon, setIcon] = useState('🏝️');
  const [rawSentences, setRawSentences] = useState('');
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      setError('Zadejte prosím název ostrova.');
      return;
    }

    const lines = rawSentences
      .split('\n')
      .map((l) => l.trim())
      .filter((l) => l.length > 0);

    if (lines.length === 0) {
      setError('Vložte alespoň 1 větu pro procvičování.');
      return;
    }

    const categoryId = `custom_${Date.now()}`;
    const parsedSentences: IslandSentence[] = lines.map((line, idx) => {
      // Allow line splitting with '|' for explicit translation e.g. "Hola | Ahoj"
      const parts = line.split('|').map((p) => p.trim());
      const es = parts[0];
      const en = parts[1] || `Procvičovací věta: "${es}"`;
      return {
        id: `${categoryId}_${idx + 1}`,
        es,
        en,
        category: categoryId,
        difficulty,
      };
    });

    const newCategory: IslandCategory = {
      categoryId,
      title: title.trim(),
      description: description.trim() || 'Vlastní jazykový ostrov',
      icon,
      difficulty,
      sentenceCount: parsedSentences.length,
      sentences: parsedSentences,
    };

    saveCustomIslandToStorage(userId, newCategory);
    onSaved(newCategory);
    onClose();

    // Reset form
    setTitle('');
    setDescription('');
    setRawSentences('');
    setError('');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fadeIn">
      <div className="relative w-full max-w-xl apple-glass bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] rounded-3xl p-6 md:p-8 shadow-2xl backdrop-blur-2xl">
        <button
          onClick={onClose}
          className="absolute top-5 right-5 text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition p-2 rounded-full hover:bg-[var(--card-bg-hover)]"
        >
          ✕
        </button>

        <div className="flex items-center space-x-3 mb-6">
          <span className="text-4xl">{icon}</span>
          <div>
            <h2 className="text-2xl font-black bg-gradient-to-r from-emerald-400 via-teal-300 to-indigo-400 bg-clip-text text-transparent">
              Vytvořit Vlastní Ostrov Jazyka
            </h2>
            <p className="text-xs text-[var(--text-secondary)]">
              Přidat vlastní sadu španělských vět pro stínování a vybavování
            </p>
          </div>
        </div>

        {error && (
          <div className="mb-4 p-3 rounded-xl bg-rose-500/20 border border-rose-500/30 text-rose-300 text-xs font-semibold">
            ⚠️ {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1">
              Název Ostrova *
            </label>
            <input
              type="text"
              placeholder="např. Moje věty z práce, Věty na letišti..."
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-4 py-2.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[var(--text-primary)] placeholder-[var(--text-muted)] text-sm focus:outline-none focus:border-[var(--accent-emerald)] transition"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1">Popis</label>
            <input
              type="text"
              placeholder="Krátký popis zaměření této sady"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full px-4 py-2.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[var(--text-primary)] placeholder-[var(--text-muted)] text-sm focus:outline-none focus:border-[var(--accent-emerald)] transition"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1">Náročnost</label>
              <select
                value={difficulty}
                onChange={(e) => setDifficulty(e.target.value as 'A1' | 'A2' | 'B1')}
                className="w-full px-4 py-2.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[var(--text-primary)] text-sm focus:outline-none focus:border-[var(--accent-emerald)] transition"
              >
                <option value="A1">A1 - Začátečník</option>
                <option value="A2">A2 - Mírně pokročilý</option>
                <option value="B1">B1 - Pokročilý</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1">Ikona</label>
              <div className="flex space-x-1 overflow-x-auto p-1 bg-[var(--card-bg-hover)] border border-[var(--card-border)] rounded-xl">
                {ICONS.map((ic) => (
                  <button
                    key={ic}
                    type="button"
                    onClick={() => setIcon(ic)}
                    className={`p-2 rounded-lg text-lg transition ${
                      icon === ic ? 'bg-emerald-500/30 border border-emerald-400' : 'hover:bg-white/10'
                    }`}
                  >
                    {ic}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1">
              Španělské Věty (jedna na řádek, volitelně s &quot;|&quot; a překladem) *
            </label>
            <textarea
              rows={6}
              placeholder={`Vivo en Praga. | Bydlím v Praze.\nMe gusta viajar por España. | Rád cestuji po Španělsku.\n¿Dónde está el hotel?`}
              value={rawSentences}
              onChange={(e) => setRawSentences(e.target.value)}
              className="w-full px-4 py-2.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[var(--text-primary)] placeholder-[var(--text-muted)] font-mono text-xs focus:outline-none focus:border-[var(--accent-emerald)] transition"
            />
            <p className="text-[11px] text-[var(--text-secondary)] mt-1">
              💡 Tip: Můžete zadat i jen španělské věty bez symbolu |.
            </p>
          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t border-white/10">
            <button
              type="button"
              onClick={onClose}
              className="px-5 py-2.5 rounded-xl bg-[var(--card-bg-hover)] hover:bg-[var(--card-bg)] border border-[var(--card-border)] text-xs font-bold text-[var(--text-secondary)] transition"
            >
              Zrušit
            </button>
            <button
              type="submit"
              className="px-6 py-2.5 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-slate-950 font-bold text-xs shadow-lg shadow-emerald-500/20 transition transform active:scale-95"
            >
              🚀 Vytvořit Ostrov
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { LiveTutorSession, LiveStatus, LIVE_MODEL, LIVE_VOICES } from '@/lib/ai/live-session';
import { IslandCategory } from '@/lib/data/islands-parser';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';
import { soundEngine } from '@/lib/audio/sound-engine';

interface IslandRecallSessionProps {
  category: IslandCategory;
  onClose: () => void;
}

export default function IslandRecallSession({ category, onClose }: IslandRecallSessionProps) {
  const { language } = useAppLanguage();
  const t = getTranslation(language);
  const [status, setStatus] = useState<LiveStatus>('idle');
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [voiceId, setVoiceId] = useState<(typeof LIVE_VOICES)[number]['id']>('Aoede');
  const sessionRef = useRef<LiveTutorSession | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const apiKey = process.env.NEXT_PUBLIC_GEMINI_API_KEY || '';

  const STATUS_CONFIG: Record<LiveStatus, { label: string; color: string; pulse: boolean }> = {
    idle:       { label: t.idleStatus,        color: 'text-[var(--text-secondary)]',  pulse: false },
    connecting: { label: t.connectingStatus,  color: 'text-amber-400',                pulse: true  },
    ready:      { label: t.ready,             color: 'text-emerald-400',              pulse: false },
    listening:  { label: t.listeningStatus,  color: 'text-rose-400',                 pulse: true  },
    speaking:   { label: t.speakingStatus,   color: 'text-cyan-400',                 pulse: true  },
    error:      { label: t.error,             color: 'text-rose-400',                 pulse: false },
    closed:     { label: t.close,             color: 'text-[var(--text-secondary)]',  pulse: false },
  };

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    return () => { sessionRef.current?.disconnect(); };
  }, []);

  const handleTranscript = useCallback((role: 'user' | 'model', text: string) => {
    setMessages(prev => {
      if (prev.length > 0 && prev[prev.length - 1].role === role) {
        const updated = [...prev];
        updated[updated.length - 1] = { ...updated[updated.length - 1], text: updated[updated.length - 1].text + ' ' + text };
        return updated;
      }
      return [...prev, { role, text }];
    });
  }, []);

  const langLabel = language === 'sk' ? 'Slovak' : language === 'en' ? 'English' : 'Czech';
  const langCode = language === 'sk' ? 'sk' : language === 'en' ? 'en' : 'cs';

  const sentenceList = category.sentences.slice(0, 30).map((s, i) => {
    const tr = s.translations?.[langCode as 'en' | 'cs' | 'sk'] || s.en || s.es;
    return `${i + 1}. ES: "${s.es}" | ${langLabel}: "${tr}"`;
  }).join('\n');

  const systemInstruction = `You are an enthusiastic Spanish language coach running a hands-free Active Recall drill session.
The student is learning Spanish. Their native language is ${langLabel}.
You are working through this sentence list from the "${category.title}" category:
${sentenceList}

YOUR JOB:
1. Say the sentence translation in ${langLabel} (e.g. "The apple is red.")
2. Ask student to say it in Spanish.
3. Wait for their microphone answer.
4. Give SHORT instant feedback in ${langLabel} (1 sentence max) and immediately move to the next sentence.`;

  const startSession = useCallback(async () => {
    if (!apiKey) { setErrorMsg('Chybí NEXT_PUBLIC_GEMINI_API_KEY'); return; }
    soundEngine.playTick();
    setMessages([]);
    setErrorMsg(null);

    const session = new LiveTutorSession(apiKey, {
      onStatusChange: setStatus,
      onTranscript: handleTranscript,
      onError: setErrorMsg,
    });
    sessionRef.current = session;

    await session.connect({
      mode: '__island_recall__',
      topic: category.title,
      nativeLanguage: language as any,
      level: (category.difficulty as any) || 'A1',
      voiceId,
      situation: systemInstruction,
    });
  }, [apiKey, language, category, handleTranscript, systemInstruction, voiceId]);

  const stopSession = useCallback(async () => {
    soundEngine.playUntick();
    await sessionRef.current?.disconnect();
    sessionRef.current = null;
    setStatus('idle');
  }, []);

  const isActive = status === 'listening' || status === 'speaking';
  const statusCfg = STATUS_CONFIG[status];

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-2 sm:p-4 bg-[var(--nav-bg)]/70 backdrop-blur-xl animate-fade-in overflow-y-auto">
      <div className="relative w-full max-w-lg apple-glass bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] rounded-3xl shadow-2xl flex flex-col my-auto max-h-[96vh] sm:max-h-[90vh] overflow-hidden animate-scale-in">

        {/* Header */}
        <div className="flex items-center justify-between p-3.5 sm:p-5 border-b border-[var(--card-border)] bg-[var(--card-bg-hover)] shrink-0">
          <div>
            <div className="flex items-center gap-2">
              <div className={`w-2.5 h-2.5 rounded-full ${
                status === 'listening'  ? 'bg-rose-400 animate-pulse' :
                status === 'speaking'   ? 'bg-cyan-400 animate-pulse' :
                status === 'connecting' ? 'bg-amber-400 animate-pulse' :
                status === 'ready'      ? 'bg-emerald-400' : 'bg-[var(--text-muted)]'
              }`} />
              <h2 className="font-black text-[var(--text-primary)] text-sm sm:text-base">🤖 {t.recallCoachTitle}</h2>
              <span className="text-[9px] sm:text-[10px] font-mono bg-[var(--accent-blue)]/15 text-[var(--accent-blue)] border border-[var(--accent-blue)]/30 px-1.5 py-0.5 rounded-full">
                {LIVE_MODEL.split('/')[1] || LIVE_MODEL}
              </span>
            </div>
            <p className={`text-[11px] sm:text-xs mt-0.5 font-mono ${statusCfg.color} ${statusCfg.pulse ? 'animate-pulse' : ''}`}>
              {statusCfg.label}
            </p>
          </div>
          <button onClick={() => { stopSession(); onClose(); }}
            className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] text-2xl leading-none cursor-pointer transition px-2 py-1">×</button>
        </div>

        {/* Body Container */}
        <div className="flex-1 overflow-y-auto space-y-3 p-3.5 sm:p-5 custom-scrollbar">
          {/* Audio orb */}
          <div className="flex justify-center py-2 relative">
            <div className={`relative flex items-center justify-center w-20 h-20 sm:w-24 sm:h-24 rounded-full transition-all duration-500 ${
              status === 'listening' ? 'bg-rose-500/15 shadow-[0_0_50px_rgba(244,63,94,0.5)]' :
              status === 'speaking'  ? 'bg-cyan-500/15 shadow-[0_0_50px_rgba(6,182,212,0.5)]' :
              'bg-[var(--card-bg-hover)] border border-[var(--card-border)]'
            }`}>
              {isActive && (
                <>
                  <div className={`absolute inset-0 rounded-full border-2 animate-ping opacity-30 ${status === 'listening' ? 'border-rose-400' : 'border-indigo-400'}`} />
                  <div className={`absolute inset-[-6px] rounded-full border animate-pulse opacity-20 ${status === 'listening' ? 'border-rose-300' : 'border-indigo-300'}`} />
                </>
              )}
              <div className="text-3xl select-none">
                {status === 'listening'  ? '🎙️' :
                 status === 'speaking'   ? '🔊' :
                 status === 'connecting' ? '⏳' :
                 status === 'error'      ? '⚠️' : '🤖'}
              </div>
            </div>
          </div>

          {/* Info card when idle */}
          {status === 'idle' && (
            <div className="p-3.5 rounded-2xl bg-[var(--accent-blue)]/10 border border-[var(--accent-blue)]/30 text-xs text-[var(--text-primary)] space-y-1.5">
              <p className="font-bold text-[var(--accent-blue)]">📋 {t.howItWorksTitle}</p>
              <p>{t.howItWorks1}</p>
              <p>{t.howItWorks2}</p>
              <p>{t.howItWorks3}</p>
            </div>
          )}

          {/* Transcript */}
          <div ref={scrollRef} className="space-y-2.5 min-h-[100px] max-h-[220px] overflow-y-auto p-2 bg-[var(--card-bg-hover)] rounded-2xl border border-[var(--card-border)]">
            {messages.length === 0 && status === 'connecting' && (
              <div className="text-center py-4 text-amber-400 text-xs animate-pulse font-mono">{t.connectingStatus}</div>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex gap-2 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className="text-base shrink-0">{m.role === 'user' ? '🧑‍🎓' : '🤖'}</div>
                <div className={`px-3 py-2 rounded-2xl text-xs sm:text-sm leading-relaxed max-w-[85%] ${
                  m.role === 'user'
                    ? 'bg-emerald-500/20 border border-emerald-500/40 text-[var(--text-primary)]'
                    : 'bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)]'
                }`}>{m.text}</div>
              </div>
            ))}
          </div>

          {errorMsg && (
            <div className="px-3 py-2 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs font-mono">
              ⚠️ {errorMsg}
            </div>
          )}

          {isActive && (
            <div className="flex flex-wrap gap-1.5 justify-center py-1">
              <button onClick={() => sessionRef.current?.sendTextMessage('Skip to next sentence please.')}
                className="px-2.5 py-1.5 rounded-xl bg-amber-500/20 hover:bg-amber-500/30 border border-amber-500/40 text-amber-300 text-[11px] font-bold transition cursor-pointer">
                ⏭️ {language === 'en' ? 'Skip' : language === 'sk' ? 'Preskočiť' : 'Přeskočit'}
              </button>
              <button onClick={() => sessionRef.current?.sendTextMessage('Repeat the sentence please.')}
                className="px-2.5 py-1.5 rounded-xl bg-cyan-500/20 hover:bg-cyan-500/30 border border-cyan-500/40 text-cyan-300 text-[11px] font-bold transition cursor-pointer">
                🔄 {t.repeatBtn}
              </button>
              <button onClick={() => sessionRef.current?.sendTextMessage('Give me the answer please.')}
                className="px-2.5 py-1.5 rounded-xl bg-indigo-500/20 hover:bg-indigo-500/30 border border-indigo-500/40 text-indigo-300 text-[11px] font-bold transition cursor-pointer">
                💡 {t.hintBtn}
              </button>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-3.5 sm:p-5 border-t border-[var(--card-border)] bg-[var(--card-bg-hover)] flex flex-col gap-2.5 shrink-0">
          {!isActive && status !== 'connecting' && (
            <div className="flex items-center gap-1.5 flex-wrap justify-center">
              <span className="text-[11px] text-[var(--text-secondary)] font-mono">{t.voiceLabel}</span>
              {LIVE_VOICES.map((v) => (
                <button
                  key={v.id}
                  onClick={() => {
                    soundEngine.playTick();
                    setVoiceId(v.id);
                  }}
                  className={`px-2.5 py-1 rounded-xl text-[11px] font-bold border transition cursor-pointer ${
                    voiceId === v.id
                      ? 'bg-[var(--accent-blue)] text-white border-[var(--accent-blue)]'
                      : 'bg-[var(--card-bg)] border-[var(--card-border)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                  }`}
                >
                  {v.id} ({v.gender === 'female' ? t.voiceFemale : t.voiceMale})
                </button>
              ))}
            </div>
          )}

          <div className="flex gap-2 justify-center">
            {status === 'idle' || status === 'closed' || status === 'error' ? (
              <button
                onClick={startSession}
                disabled={!apiKey}
                className="w-full sm:w-auto px-7 py-3 rounded-2xl bg-emerald-500 hover:bg-emerald-400 font-black text-slate-950 text-xs sm:text-sm transition cursor-pointer shadow-lg hover:scale-105 active:scale-95 disabled:opacity-40"
              >
                ▶ {t.startRecallSession}
              </button>
            ) : (
              <button
                onClick={stopSession}
                className="w-full sm:w-auto px-7 py-3 rounded-2xl bg-rose-600 hover:bg-rose-500 font-black text-white text-xs sm:text-sm transition cursor-pointer shadow-lg hover:scale-105 active:scale-95"
              >
                ⏹ {t.endSession}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import { IslandCategory, IslandSentence, getLocalizedIslandTitle } from '@/lib/data/islands-parser';
import { soundEngine } from '@/lib/audio/sound-engine';
import { addPointsToUser, getIslandProgressSnapshot, saveIslandProgressSnapshot, saveIslandProgressToFirestore } from '@/lib/firebase/db';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';
import IslandRecallSession from '@/components/islands/IslandRecallSession';

interface IslandTrainerProps {
  userId: string;
  category: IslandCategory;
  onClose: () => void;
}

type TrainerMode = 'shadowing' | 'active_recall';
type StatsTimeframe = 'today' | 'all_time';

export default function IslandTrainer({ userId, category, onClose }: IslandTrainerProps) {
  const { language } = useAppLanguage();
  const t = getTranslation(language);

  const [mode, setMode] = useState<TrainerMode>('shadowing');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showTranslation, setShowTranslation] = useState(true);
  const [audioEnabled, setAudioEnabled] = useState(true);
  const [isShuffled, setIsShuffled] = useState(false);
  const [sentences, setSentences] = useState<IslandSentence[]>(category.sentences);

  // Toggle shuffle state
  const toggleShuffle = () => {
    soundEngine.playTick();
    if (!isShuffled) {
      const shuffled = [...category.sentences].sort(() => Math.random() - 0.5);
      setSentences(shuffled);
      setIsShuffled(true);
    } else {
      setSentences(category.sentences);
      setIsShuffled(false);
    }
    setCurrentIndex(0);
  };

  // Settings & Looper Controls
  const [isPlaying, setIsPlaying] = useState(false);
  const [pauseDuration, setPauseDuration] = useState<number>(2.5);
  const [repetitions, setRepetitions] = useState<number>(1);
  const [playbackSpeed, setPlaybackSpeed] = useState<number>(1.0);
  const [showSettings, setShowSettings] = useState(false);

  // Runtime State
  const [currentRep, setCurrentRep] = useState<number>(1);
  const [shadowingCountdown, setShadowingCountdown] = useState<number>(0);
  const [isShadowingPhase, setIsShadowingPhase] = useState<boolean>(false);

  // Active Recall & Voice Rec State
  const [isListening, setIsListening] = useState(false);
  const [spokenTranscript, setSpokenTranscript] = useState('');
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [aiEvaluation, setAiEvaluation] = useState<{
    isCorrect: boolean;
    accuracyScore: number;
    feedbackText: string;
    correctSpanish: string;
  } | null>(null);

  // Stats & Progress Persistence
  const [statsTimeframe, setStatsTimeframe] = useState<StatsTimeframe>('today');
  const [masteredIds, setMasteredIds] = useState<Set<string>>(new Set());
  const [practicedIds, setPracticedIds] = useState<Set<string>>(new Set());
  const [totalReps, setTotalReps] = useState<number>(0);
  const [stars, setStars] = useState<Record<string, number>>({});

  useEffect(() => {
    const saved = getIslandProgressSnapshot(userId, category.categoryId);
    setMasteredIds(new Set(saved.masteredIds));
    setPracticedIds(new Set(saved.practicedIds));
    setTotalReps(saved.totalReps || 0);
    setStars(saved.stars || {});
  }, [userId, category.categoryId]);

  useEffect(() => {
    saveIslandProgressSnapshot(userId, category.categoryId, {
      masteredIds: Array.from(masteredIds),
      practicedIds: Array.from(practicedIds),
      totalReps,
      stars,
    });
  }, [userId, category.categoryId, masteredIds, practicedIds, totalReps, stars]);

  const currentSentence = sentences[currentIndex] || sentences[0];
  const totalSentences = category.sentences.length;
  const localizedCategoryTitle = getLocalizedIslandTitle(category.categoryId, language);

  // Refs
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const recognitionRef = useRef<any>(null);
  const activeCardRef = useRef<HTMLDivElement | null>(null);

  // Auto-scroll active sentence card into view
  useEffect(() => {
    if (activeCardRef.current) {
      activeCardRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [currentIndex]);

  const clearAllTimers = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (intervalRef.current) clearInterval(intervalRef.current);
    if (typeof window !== 'undefined' && window.speechSynthesis) {
      window.speechSynthesis.cancel();
    }
  }, []);

  // Helper to get clean translation without prefixes
  const getSentenceTranslation = useCallback(
    (sentence: IslandSentence): string => {
      if (sentence.translations) {
        if (language === 'sk' && sentence.translations.sk) return sentence.translations.sk;
        if (language === 'en' && sentence.translations.en) return sentence.translations.en;
        if (sentence.translations.cs) return sentence.translations.cs;
      }
      return sentence.en || sentence.es;
    },
    [language]
  );

  // Speak AI Voice Prompt / Evaluation in User's selected language
  const speakUserLangPrompt = useCallback(
    (text: string, onEnd?: () => void) => {
      if (typeof window === 'undefined' || !window.speechSynthesis || !audioEnabled) {
        if (onEnd) onEnd();
        return;
      }

      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);

      let targetLang = 'cs-CZ';
      if (language === 'sk') targetLang = 'sk-SK';
      if (language === 'en') targetLang = 'en-US';

      utterance.lang = targetLang;
      utterance.rate = playbackSpeed;

      const voices = window.speechSynthesis.getVoices();
      const targetVoice = voices.find((v) => v.lang.startsWith(targetLang.slice(0, 2)));
      if (targetVoice) utterance.voice = targetVoice;

      if (onEnd) {
        utterance.onend = () => onEnd();
        utterance.onerror = () => onEnd();
      }

      window.speechSynthesis.speak(utterance);
    },
    [audioEnabled, language, playbackSpeed]
  );

  // Trigger Voice Prompt when entering Active Recall mode or selecting a new sentence
  useEffect(() => {
    if (mode === 'active_recall' && currentSentence) {
      const translation = getSentenceTranslation(currentSentence);
      let promptText = '';
      if (language === 'sk') {
        promptText = `Prelož do španielčiny: ${translation}`;
      } else if (language === 'en') {
        promptText = `Translate to Spanish: ${translation}`;
      } else {
        promptText = `Přelož do španělštiny: ${translation}`;
      }
      speakUserLangPrompt(promptText);
    }
  }, [mode, currentIndex, currentSentence, language, getSentenceTranslation, speakUserLangPrompt]);

  // Trilingual TTS Player (Spanish -> Foreign Language if translation toggle is ON)
  const speakSentenceSequence = useCallback(
    (sentence: IslandSentence, onEnd: () => void) => {
      if (typeof window === 'undefined' || !window.speechSynthesis || !audioEnabled) {
        onEnd();
        return;
      }

      window.speechSynthesis.cancel();
      const voices = window.speechSynthesis.getVoices();

      const esParts: string[] = [];
      if (sentence.questionEs) esParts.push(sentence.questionEs);
      if (sentence.answerEs) esParts.push(sentence.answerEs);
      if (esParts.length === 0) esParts.push(sentence.es);

      const speakEsPart = (index: number) => {
        if (index >= esParts.length) {
          if (showTranslation) {
            const translationText = getSentenceTranslation(sentence);
            speakUserLangPrompt(translationText, onEnd);
          } else {
            onEnd();
          }
          return;
        }

        const esUtterance = new SpeechSynthesisUtterance(esParts[index]);
        esUtterance.lang = 'es-ES';
        esUtterance.rate = playbackSpeed;
        const esVoice = voices.find((v) => v.lang.startsWith('es'));
        if (esVoice) esUtterance.voice = esVoice;

        esUtterance.onend = () => speakEsPart(index + 1);
        esUtterance.onerror = () => speakEsPart(index + 1);

        window.speechSynthesis.speak(esUtterance);
      };

      speakEsPart(0);
    },
    [audioEnabled, showTranslation, playbackSpeed, getSentenceTranslation, speakUserLangPrompt]
  );

  // Navigation
  const handleNext = useCallback(() => {
    clearAllTimers();
    setIsShadowingPhase(false);
    setAiEvaluation(null);
    setSpokenTranscript('');
    setCurrentRep(1);
    setCurrentIndex((prev) => (prev + 1 < totalSentences ? prev + 1 : 0));
  }, [totalSentences, clearAllTimers]);

  const handlePrev = useCallback(() => {
    clearAllTimers();
    setIsShadowingPhase(false);
    setAiEvaluation(null);
    setSpokenTranscript('');
    setCurrentRep(1);
    setCurrentIndex((prev) => (prev - 1 >= 0 ? prev - 1 : totalSentences - 1));
  }, [totalSentences, clearAllTimers]);

  // Shadowing Looper Execution
  const runShadowingLoop = useCallback(() => {
    if (!isPlaying) return;

    setPracticedIds((prev) => new Set(prev).add(currentSentence.id));
    setTotalReps((prev) => prev + 1);

    speakSentenceSequence(currentSentence, () => {
      setIsShadowingPhase(true);
      setShadowingCountdown(pauseDuration);

      const startTime = Date.now();
      const durationMs = pauseDuration * 1000;

      intervalRef.current = setInterval(() => {
        const elapsed = (Date.now() - startTime) / 1000;
        const remaining = Math.max(0, pauseDuration - elapsed);
        setShadowingCountdown(remaining);
      }, 100);

      timeoutRef.current = setTimeout(() => {
        if (intervalRef.current) clearInterval(intervalRef.current);
        setIsShadowingPhase(false);

        setCurrentRep((prev) => {
          if (prev < repetitions) {
            timeoutRef.current = setTimeout(() => {
              runShadowingLoop();
            }, 200);
            return prev + 1;
          } else {
            soundEngine.playTick();
            timeoutRef.current = setTimeout(() => {
              handleNext();
            }, 300);
            return 1;
          }
        });
      }, durationMs);
    });
  }, [isPlaying, currentSentence, speakSentenceSequence, pauseDuration, repetitions, handleNext]);

  useEffect(() => {
    if (mode === 'shadowing' && isPlaying) {
      runShadowingLoop();
    } else {
      clearAllTimers();
      setIsShadowingPhase(false);
    }
    return () => clearAllTimers();
  }, [isPlaying, mode, currentIndex, runShadowingLoop, clearAllTimers]);

  // Web Speech Recognition for Active Recall
  const startVoiceRecording = () => {
    if (typeof window === 'undefined') return;
    const SpeechRecognition =
      (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

    if (!SpeechRecognition) {
      alert('Váš prohlížeč nepodporuje rozpoznání řeči. Použijte Chrome nebo Safari.');
      return;
    }

    try {
      window.speechSynthesis.cancel();
      const recognition = new SpeechRecognition();
      recognition.lang = 'es-ES';
      recognition.interimResults = true;

      recognition.onstart = () => {
        setIsListening(true);
        setSpokenTranscript('');
      };

      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; i++) {
          transcript += event.results[i][0].transcript;
        }
        setSpokenTranscript(transcript);
      };

      recognition.onerror = () => setIsListening(false);
      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
      recognition.start();
    } catch (e) {
      console.error('Failed speech recognition:', e);
      setIsListening(false);
    }
  };

  const stopVoiceRecordingAndEvaluate = () => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
    setTimeout(() => {
      handleEvaluateSpeech();
    }, 400);
  };

  // Evaluate speech & talk back verbally to user
  const handleEvaluateSpeech = async () => {
    const textToEval = spokenTranscript.trim();
    if (!textToEval) return;

    setIsEvaluating(true);
    setPracticedIds((prev) => new Set(prev).add(currentSentence.id));
    setTotalReps((prev) => prev + 1);

    try {
      const apiKey = process.env.NEXT_PUBLIC_GEMINI_API_KEY || process.env.GEMINI_API_KEY;
      let evalResult = {
        isCorrect: false,
        accuracyScore: 70,
        feedbackText: '',
        correctSpanish: currentSentence.es,
      };

      if (!apiKey) {
        const isExact =
          textToEval.toLowerCase() === currentSentence.es.trim().toLowerCase();
        evalResult = {
          isCorrect: isExact,
          accuracyScore: isExact ? 100 : 75,
          feedbackText: isExact
            ? language === 'sk'
              ? 'Výborne! Vaša výslovnosť je presná.'
              : language === 'en'
              ? 'Excellent! Your pronunciation is accurate.'
              : 'Výborně! Vaše výslovnost je přesná.'
            : language === 'sk'
            ? `Povedali ste: "${textToEval}". Správny tvar je: "${currentSentence.es}".`
            : language === 'en'
            ? `You said: "${textToEval}". Target is: "${currentSentence.es}".`
            : `Řekli jste: "${textToEval}". Správný tvar je: "${currentSentence.es}".`,
          correctSpanish: currentSentence.es,
        };
      } else {
        const ai = new GoogleGenAI({ apiKey });
        const evalLang = language === 'sk' ? 'Slovak' : language === 'en' ? 'English' : 'Czech';

        const prompt = `Target Spanish sentence: "${currentSentence.es}"
User spoken Spanish transcript: "${textToEval}"

Evaluate user performance. Respond ONLY in JSON with keys:
{
  "isCorrect": boolean,
  "accuracyScore": number (0-100),
  "feedbackText": "Concise feedback in ${evalLang} (1-2 sentences)"
}`;

        let responseText = '';
        try {
          const response = await ai.models.generateContent({
            model: 'gemini-3.1-flash-live-preview',
            contents: [{ role: 'user', parts: [{ text: prompt }] }],
            config: { responseMimeType: 'application/json', temperature: 0.2 },
          });
          responseText = response.text || '';
        } catch {
          const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: [{ role: 'user', parts: [{ text: prompt }] }],
            config: { responseMimeType: 'application/json', temperature: 0.2 },
          });
          responseText = response.text || '';
        }

        const parsed = JSON.parse(responseText);
        evalResult = {
          isCorrect: Boolean(parsed.isCorrect),
          accuracyScore: Number(parsed.accuracyScore) || 80,
          feedbackText: String(parsed.feedbackText || 'Dobrá práce!'),
          correctSpanish: currentSentence.es,
        };
      }

      setAiEvaluation(evalResult);

      if (evalResult.isCorrect) {
        soundEngine.playTick();
      }

      // AI Voice Assistant talks back the evaluation result in user's main language!
      speakUserLangPrompt(evalResult.feedbackText);
    } catch (err) {
      console.error('Speech evaluation failed:', err);
    } finally {
      setIsEvaluating(false);
    }
  };

  const handleGradeSentence = async (sentenceId: string, starCount: number) => {
    soundEngine.playTick();
    setStars((prev) => ({ ...prev, [sentenceId]: starCount }));

    if (starCount >= 4 && !masteredIds.has(sentenceId)) {
      const updated = new Set(masteredIds);
      updated.add(sentenceId);
      setMasteredIds(updated);

      await addPointsToUser(userId, 5);
      await saveIslandProgressToFirestore(userId, category.categoryId, Array.from(updated), {
        practicedIds: Array.from(practicedIds),
        totalReps,
        stars: { ...stars, [sentenceId]: starCount },
      });

      if (updated.size === totalSentences) {
        soundEngine.playVictoryFanfare();
      }
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-xl p-2 sm:p-4 overflow-hidden animate-fade-in">
      <div className="relative w-full max-w-6xl h-[96vh] sm:h-[92vh] apple-glass bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] rounded-2xl sm:rounded-3xl shadow-2xl backdrop-blur-2xl flex flex-col overflow-hidden">
        
        {/* Top Header Bar */}
        <div className="flex flex-row items-center justify-between px-3 sm:px-5 py-2 sm:py-3 border-b border-[var(--card-border)] bg-[var(--card-bg-hover)] gap-2 shrink-0 overflow-x-auto">
          <div className="flex items-center space-x-2 sm:space-x-3 min-w-0 shrink-0">
            <button
              onClick={() => {
                clearAllTimers();
                onClose();
              }}
              className="p-1.5 px-2 sm:px-2.5 rounded-xl bg-[var(--card-bg)] hover:bg-[var(--card-bg-hover)] text-[var(--text-primary)] transition flex items-center space-x-1 text-xs font-bold cursor-pointer shrink-0 border border-[var(--card-border)] min-h-[44px] sm:min-h-auto min-w-[44px] sm:min-w-auto"
            >
              <span className="hidden sm:inline">{t.back}</span>
              <span className="sm:hidden">←</span>
            </button>

            <div className="truncate min-w-0">
              <h2 className="text-xs sm:text-sm md:text-base font-extrabold text-[var(--text-primary)] flex items-center gap-1.5 truncate">
                <span className="shrink-0">{category.icon}</span>
                <span className="truncate">{localizedCategoryTitle}</span>
              </h2>
            </div>
          </div>

          {/* Mode Pill & Audio Toggles */}
          <div className="flex items-center justify-end gap-1 sm:gap-1.5 overflow-x-auto pb-0.5 sm:pb-0 shrink-0">
            {/* Play Button */}
            <button
              onClick={() => {
                soundEngine.playTick();
                setIsPlaying(!isPlaying);
              }}
              className={`px-3.5 py-1.5 rounded-xl text-xs font-black transition flex items-center space-x-1.5 cursor-pointer shadow-lg shrink-0 ${
                isPlaying
                  ? 'bg-amber-500 hover:bg-amber-400 text-slate-950'
                  : 'bg-emerald-500 hover:bg-emerald-400 text-slate-950'
              }`}
            >
              <span>{isPlaying ? `⏸️ ${t.pauseBtn}` : `▶️ ${t.startBtn}`}</span>
              <span className="px-1.5 py-0.5 rounded-lg bg-black/20 font-mono text-[10px] text-slate-950 font-bold">
                {repetitions}x
              </span>
            </button>

            {/* Mode Switcher */}
            <div className="p-0.5 bg-[var(--card-bg)] border border-[var(--card-border)] rounded-xl flex items-center shrink-0">
              <button
                onClick={() => {
                  soundEngine.playTick();
                  setIsPlaying(false);
                  setMode('shadowing');
                }}
                className={`px-2.5 py-1 rounded-lg text-xs font-bold transition flex items-center space-x-1 cursor-pointer ${
                  mode === 'shadowing'
                    ? 'bg-[var(--accent-blue)] text-white shadow-md'
                    : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                }`}
              >
                <span>{t.shadowMode}</span>
              </button>
              <button
                onClick={() => {
                  soundEngine.playTick();
                  setIsPlaying(false);
                  setMode('active_recall');
                }}
                className={`px-2.5 py-1 rounded-lg text-xs font-bold transition flex items-center space-x-1 cursor-pointer ${
                  mode === 'active_recall'
                    ? 'bg-emerald-500 text-slate-950 shadow-md font-black'
                    : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                }`}
              >
                <span>{t.recallMode}</span>
              </button>
            </div>

            {/* Shuffle Button */}
            <button
              onClick={toggleShuffle}
              className={`px-2.5 py-1.5 rounded-xl border text-xs font-bold transition cursor-pointer shrink-0 flex items-center gap-1 ${
                isShuffled
                  ? 'bg-purple-500 text-white border-purple-400 shadow-md'
                  : 'bg-[var(--card-bg)] border-[var(--card-border)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
              }`}
              title={isShuffled ? t.originalOrder : t.shuffleOrder}
            >
              <span>🔀</span>
              <span className="hidden md:inline">{isShuffled ? t.shuffleOrder : t.originalOrder}</span>
            </button>

            {/* Translation Toggle Button */}
            <button
              onClick={() => {
                soundEngine.playTick();
                setShowTranslation(!showTranslation);
              }}
              className={`p-2 rounded-xl border text-xs font-bold transition cursor-pointer shrink-0 ${
                showTranslation
                  ? 'bg-[var(--accent-blue)]/20 border-[var(--accent-blue)] text-[var(--accent-blue)]'
                  : 'bg-[var(--card-bg)] border-[var(--card-border)] text-[var(--text-secondary)]'
              }`}
              title="Translation"
            >
              🌐
            </button>

            {/* Audio Toggle Button */}
            <button
              onClick={() => {
                soundEngine.playTick();
                setAudioEnabled(!audioEnabled);
              }}
              className={`p-2 rounded-xl border text-xs font-bold transition cursor-pointer shrink-0 ${
                audioEnabled
                  ? 'bg-[var(--accent-blue)]/20 border-[var(--accent-blue)] text-[var(--accent-blue)]'
                  : 'bg-[var(--card-bg)] border-[var(--card-border)] text-[var(--text-secondary)]'
              }`}
              title="Audio"
            >
              🎧
            </button>

            {/* Settings Button */}
            <button
              onClick={() => {
                soundEngine.playTick();
                setShowSettings(!showSettings);
              }}
              className="p-2 rounded-xl bg-[var(--card-bg)] hover:bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition cursor-pointer shrink-0"
              title="Settings"
            >
              ⚙️
            </button>
          </div>
        </div>

        {/* Looper Settings Bar */}
        {showSettings && (
          <div className="px-6 py-3 bg-[var(--card-bg-hover)] border-b border-[var(--card-border)] grid grid-cols-1 sm:grid-cols-3 gap-4 text-xs animate-fadeIn">
            <div>
              <label className="block text-[var(--text-secondary)] font-semibold mb-1">
                ⏱️ {t.shadowPause} <span className="text-[var(--accent-blue)] font-bold">{pauseDuration}s</span>
              </label>
              <input
                type="range"
                min="1.0"
                max="5.0"
                step="0.5"
                value={pauseDuration}
                onChange={(e) => setPauseDuration(parseFloat(e.target.value))}
                className="w-full accent-[var(--accent-blue)] cursor-pointer"
              />
            </div>
            <div>
              <label className="block text-[var(--text-secondary)] font-semibold mb-1">
                🔁 {t.repCount} <span className="text-[var(--accent-blue)] font-bold">{repetitions}x</span>
              </label>
              <input
                type="range"
                min="1"
                max="5"
                step="1"
                value={repetitions}
                onChange={(e) => setRepetitions(parseInt(e.target.value))}
                className="w-full accent-[var(--accent-blue)] cursor-pointer"
              />
            </div>
            <div>
              <label className="block text-[var(--text-secondary)] font-semibold mb-1">
                ⏩ {t.voiceSpeed} <span className="text-[var(--accent-blue)] font-bold">{playbackSpeed}x</span>
              </label>
              <input
                type="range"
                min="0.7"
                max="1.3"
                step="0.1"
                value={playbackSpeed}
                onChange={(e) => setPlaybackSpeed(parseFloat(e.target.value))}
                className="w-full accent-[var(--accent-blue)] cursor-pointer"
              />
            </div>
          </div>
        )}

        {/* Main Content Layout */}
        <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
          {/* Sentence List View */}
          <div className="flex-1 p-4 md:p-6 overflow-y-auto space-y-4 custom-scrollbar">
            {isShadowingPhase && (
              <div className="p-3 rounded-2xl bg-emerald-500/20 border border-emerald-500/40 text-center animate-pulse flex items-center justify-center space-x-2">
                <span className="text-[var(--text-primary)] font-bold">{t.speakNowPrompt}</span>
                <span className="font-mono font-bold text-emerald-400">
                  ({shadowingCountdown.toFixed(1)}s)
                </span>
              </div>
            )}

            {sentences.map((sent, idx) => {
              const isActive = idx === currentIndex;
              const sentenceStars = stars[sent.id] || 0;
              const isMastered = masteredIds.has(sent.id);
              const translationText = getSentenceTranslation(sent);

              return (
                <div
                  key={sent.id}
                  ref={isActive ? activeCardRef : null}
                  onClick={() => {
                    clearAllTimers();
                    setCurrentIndex(idx);
                  }}
                  className={`relative p-5 rounded-2xl transition duration-200 border cursor-pointer flex flex-col md:flex-row items-start md:items-center justify-between gap-4 glass-panel ${
                    isActive
                      ? 'border-emerald-500 shadow-xl ring-2 ring-emerald-500/30 bg-emerald-500/10'
                      : 'hover:border-[var(--card-border-hover)]'
                  }`}
                >
                  <div className="flex items-start space-x-3 flex-1">
                    <div className="flex flex-col space-y-2 items-center">
                      <span className="text-[11px] font-mono font-bold text-[var(--accent-blue)] px-2 py-0.5 rounded-md bg-[var(--accent-blue)]/10 border border-[var(--accent-blue)]/20">
                        #{idx + 1}
                      </span>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          clearAllTimers();
                          setCurrentIndex(idx);
                          speakSentenceSequence(sent, () => {});
                        }}
                        className="p-1.5 rounded-lg bg-[var(--card-bg)] hover:bg-[var(--card-bg-hover)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition text-xs cursor-pointer border border-[var(--card-border)]"
                        title="Přehrát"
                      >
                        🔊
                      </button>
                    </div>

                    <div className="space-y-1">
                      {sent.questionEs ? (
                        <div>
                          <p className="text-base md:text-lg font-bold text-[var(--text-primary)] leading-relaxed">
                            {sent.questionEs}
                          </p>
                          {sent.answerEs && (
                            <p className="text-base md:text-lg font-extrabold text-[var(--accent-blue)] leading-relaxed mt-1">
                              {sent.answerEs}
                            </p>
                          )}
                        </div>
                      ) : (
                        <p className="text-base md:text-lg font-bold text-[var(--text-primary)] leading-relaxed">
                          {sent.es}
                        </p>
                      )}

                      {showTranslation && (
                        <p className="text-xs md:text-sm font-medium text-[var(--text-secondary)] italic">
                          {translationText}
                        </p>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center space-x-1 self-end md:self-center">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <button
                        key={star}
                        onClick={(e) => {
                          e.stopPropagation();
                          handleGradeSentence(sent.id, star);
                        }}
                        className={`text-base md:text-lg transition transform active:scale-90 cursor-pointer ${
                          star <= sentenceStars
                            ? 'text-amber-400'
                            : 'text-[var(--text-muted)] hover:text-[var(--text-secondary)]'
                        }`}
                      >
                        ★
                      </button>
                    ))}
                    {isMastered && (
                      <span className="ml-1 text-xs px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 font-bold border border-emerald-500/30">
                        ✓ {t.mastered}
                      </span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Right Info Sidebar */}
          <div className="w-full lg:w-80 p-3 md:p-5 bg-[var(--card-bg-hover)] border-t lg:border-t-0 lg:border-l border-[var(--card-border)] space-y-4 overflow-y-auto shrink-0">
            {/* Top Stats Metric Box */}
            <div className="p-3.5 rounded-2xl bg-[var(--card-bg)] border border-[var(--card-border)] space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-[var(--text-primary)]">📊 {t.islandStats}</span>
                <div className="flex p-0.5 bg-[var(--card-bg-hover)] rounded-xl border border-[var(--card-border)]">
                  <button
                    onClick={() => {
                      soundEngine.playTick();
                      setStatsTimeframe('today');
                    }}
                    className={`px-2.5 py-0.5 rounded-lg text-[11px] font-bold transition cursor-pointer ${
                      statsTimeframe === 'today'
                        ? 'bg-[var(--accent-blue)] text-white'
                        : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                    }`}
                  >
                    {t.today}
                  </button>
                  <button
                    onClick={() => {
                      soundEngine.playTick();
                      setStatsTimeframe('all_time');
                    }}
                    className={`px-2.5 py-0.5 rounded-lg text-[11px] font-bold transition cursor-pointer ${
                      statsTimeframe === 'all_time'
                        ? 'bg-[var(--accent-blue)] text-white'
                        : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                    }`}
                  >
                    {t.allTime}
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-1.5 text-center">
                <div className="p-1.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)]">
                  <span className="text-base md:text-lg font-extrabold text-[var(--accent-blue)] block leading-tight">
                    {practicedIds.size}
                  </span>
                  <span className="text-[9px] font-bold text-[var(--text-secondary)] uppercase tracking-wider">
                    {t.practiced}
                  </span>
                </div>
                <div className="p-1.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)]">
                  <span className="text-base md:text-lg font-extrabold text-amber-400 block leading-tight">
                    {totalReps}
                  </span>
                  <span className="text-[9px] font-bold text-[var(--text-secondary)] uppercase tracking-wider">
                    {t.repetitions}
                  </span>
                </div>
                <div className="p-1.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)]">
                  <span className="text-base md:text-lg font-extrabold text-emerald-400 block leading-tight">
                    {masteredIds.size}
                  </span>
                  <span className="text-[9px] font-bold text-[var(--text-secondary)] uppercase tracking-wider">
                    {t.mastered}
                  </span>
                </div>
              </div>
            </div>

            {/* Live Recall Coach Trigger */}
            {mode === 'active_recall' && (
              <IslandRecallSession
                category={category}
                onClose={() => setMode('shadowing')}
              />
            )}

            <div className="hidden md:block space-y-3">
              <div className="p-3.5 rounded-2xl bg-[var(--card-bg)] border border-[var(--card-border)] space-y-1.5">
                <div className="flex items-center space-x-2 text-[var(--accent-blue)]">
                  <span>⚡</span>
                  <span className="text-xs font-bold uppercase tracking-wider font-mono">
                    {t.howToPractice}
                  </span>
                </div>
                <p className="text-[11px] text-[var(--text-secondary)] leading-relaxed">
                  {t.shadowGuide}<br /><br />
                  {t.recallGuide}
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { UserProfile } from '@/lib/types';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';

interface LeaderboardProps {
  users: UserProfile[];
}

export default function Leaderboard({ users }: LeaderboardProps) {
  const { language } = useAppLanguage();
  const t = getTranslation(language);
  const sortedUsers = [...users].sort((a, b) => b.totalPoints - a.totalPoints);

  const renderAvatar = (avatarValue?: string) => {
    if (!avatarValue) return '👤';
    if (avatarValue.startsWith('data:image') || avatarValue.startsWith('http')) {
      return (
        <img
          src={avatarValue}
          alt="Avatar"
          className="w-full h-full object-cover rounded-full"
        />
      );
    }
    return avatarValue;
  };

  return (
    <div className="apple-glass p-6 md:p-8 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <span className="apple-pill-badge bg-amber-500/15 text-amber-400 border border-amber-500/30 mb-2">
            {t.liveLeaderboard}
          </span>
          <h2 className="apple-heading-md text-[var(--text-primary)] flex items-center gap-2">
            <span>🏆</span> {t.challengeAndPoints}
          </h2>
        </div>
        <span className="text-xs font-mono text-emerald-400 bg-emerald-500/10 px-3 py-1 rounded-full border border-emerald-500/20 animate-pulse">
          {t.realTimeSync}
        </span>
      </div>

      <div className="space-y-3">
        {sortedUsers.map((user, index) => {
          const isTop = index === 0;
          return (
            <div
              key={user.uid}
              className={`p-4 sm:p-5 rounded-2xl border flex items-center justify-between transition-all ${
                isTop
                  ? 'bg-amber-500/10 border-amber-500/40 shadow-[0_0_20px_rgba(245,158,11,0.12)]'
                  : 'bg-[var(--card-bg)] border-[var(--card-border)] hover:bg-[var(--card-bg-hover)]'
              }`}
            >
              <div className="flex items-center space-x-3.5 sm:space-x-4 min-w-0">
                {/* Medaile #1 / #2 */}
                <div
                  className={`w-9 h-9 rounded-full font-black text-xs flex items-center justify-center shrink-0 shadow-sm ${
                    isTop
                      ? 'bg-gradient-to-br from-amber-400 to-amber-600 text-slate-950 font-black'
                      : 'bg-white/10 dark:bg-white/5 border border-[var(--card-border)] text-[var(--text-secondary)] font-bold'
                  }`}
                >
                  #{index + 1}
                </div>

                {/* Avatar */}
                <div className="w-10 h-10 rounded-full bg-[var(--card-bg-hover)] border border-[var(--card-border)] flex items-center justify-center text-lg overflow-hidden shrink-0">
                  {renderAvatar(user.avatar)}
                </div>

                {/* Uživatelské jméno a streak */}
                <div className="min-w-0">
                  <div className="flex items-center space-x-1.5">
                    <span className="font-extrabold text-sm sm:text-base text-[var(--text-primary)] truncate">
                      {user.displayName}
                    </span>
                    {isTop && <span className="text-sm shrink-0">👑</span>}
                  </div>
                  <div className="text-xs text-[var(--text-secondary)] font-medium mt-0.5">
                    🔥 {user.currentStreak} {t.dayStreakLabel}
                  </div>
                </div>
              </div>

              {/* Body – perfektně čitelné na jakémkoliv pozadí */}
              <div className="text-right shrink-0 pl-3">
                <div className="text-xl sm:text-2xl font-black font-mono text-amber-500 dark:text-amber-400 tracking-tight">
                  {user.totalPoints}{' '}
                  <span className="text-xs font-semibold text-[var(--text-muted)] font-sans">
                    {t.pointsUnit}
                  </span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { LiveTutorSession, LiveStatus, LiveVoiceId, LIVE_VOICES, LIVE_MODEL } from '@/lib/ai/live-session';
import { NativeLanguage, CEFRLevel } from '@/lib/ai/gemini';
import { getTutorMemories, saveTutorMemory } from '@/lib/firebase/db';
import { soundEngine } from '@/lib/audio/sound-engine';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';

interface Message {
  role: 'user' | 'model';
  text: string;
  ts: number;
}

interface LiveTutorModalProps {
  isOpen: boolean;
  onClose: () => void;
  mode?: string;
  topic?: string;
  nativeLanguage?: NativeLanguage;
  level?: CEFRLevel;
  situation?: string;
  userName?: string;
  userId?: string;
  totalPoints?: number;
  currentStreak?: number;
}

export default function LiveTutorModal({
  isOpen,
  onClose,
  mode = 'free_conversation',
  topic = 'General Practice',
  nativeLanguage = 'cs',
  level = 'A1',
  situation,
  userName,
  userId,
  totalPoints,
  currentStreak,
}: LiveTutorModalProps) {
  const { language } = useAppLanguage();
  const t = getTranslation(language);

  const [status, setStatus] = useState<LiveStatus>('idle');
  const [messages, setMessages] = useState<Message[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [voiceId, setVoiceId] = useState<LiveVoiceId>('Aoede');
  const [savedMemories, setSavedMemories] = useState<{ topic: string; summary: string; userFacts: string[] }[]>([]);
  const sessionRef = useRef<LiveTutorSession | null>(null);
  const sessionStartedAtRef = useRef<number | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const apiKey = process.env.NEXT_PUBLIC_GEMINI_API_KEY || '';

  const STATUS_CONFIG: Record<LiveStatus, { label: string; color: string; pulse: boolean }> = {
    idle:        { label: t.idleStatus,         color: 'text-[var(--text-secondary)]',  pulse: false },
    connecting:  { label: t.liveConnecting,     color: 'text-amber-400',                pulse: true  },
    ready:       { label: t.ready,              color: 'text-emerald-400',              pulse: false },
    listening:   { label: t.liveListening,      color: 'text-rose-400',                 pulse: true  },
    speaking:    { label: t.liveSpeaking,       color: 'text-cyan-400',                 pulse: true  },
    error:       { label: t.error,              color: 'text-rose-400',                 pulse: false },
    closed:      { label: t.close,              color: 'text-[var(--text-secondary)]',  pulse: false },
  };

  useEffect(() => {
    if (!isOpen || !userId) return;

    let active = true;
    getTutorMemories(userId)
      .then((memories) => {
        if (active) setSavedMemories(memories.slice(0, 5));
      })
      .catch(() => {
        if (active) setSavedMemories([]);
      });

    return () => { active = false; };
  }, [isOpen, userId]);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  const handleTranscript = useCallback((role: 'user' | 'model', text: string) => {
    setMessages((prev) => {
      if (prev.length > 0 && prev[prev.length - 1].role === role) {
        const updated = [...prev];
        updated[updated.length - 1] = {
          ...updated[updated.length - 1],
          text: updated[updated.length - 1].text + ' ' + text,
        };
        return updated;
      }
      return [...prev, { role, text, ts: Date.now() }];
    });
  }, []);

  const handleStatusChange = useCallback((s: LiveStatus) => {
    setStatus(s);
  }, []);

  const handleError = useCallback((msg: string) => {
    setErrorMsg(msg);
  }, []);

  const startSession = useCallback(async () => {
    if (!apiKey) {
      setErrorMsg('NEXT_PUBLIC_GEMINI_API_KEY není nastaven v .env.local');
      return;
    }
    soundEngine.playTick();
    setMessages([]);
    setErrorMsg(null);
    sessionStartedAtRef.current = Date.now();

    const session = new LiveTutorSession(apiKey, {
      onStatusChange: handleStatusChange,
      onTranscript: handleTranscript,
      onError: handleError,
    });
    sessionRef.current = session;

    await session.connect({
      mode,
      topic,
      nativeLanguage,
      level,
      voiceId,
      situation,
      userName,
      totalPoints,
      currentStreak,
      memories: savedMemories,
    });
  }, [apiKey, mode, topic, nativeLanguage, level, voiceId, situation, userName, totalPoints, currentStreak, savedMemories, handleStatusChange, handleTranscript, handleError]);

  const stopSession = useCallback(async () => {
    soundEngine.playUntick();
    const elapsedMinutes = sessionStartedAtRef.current ? Math.max(1, Math.ceil((Date.now() - sessionStartedAtRef.current) / 60000)) : 0;

    if (sessionRef.current) {
      await sessionRef.current.disconnect();
      sessionRef.current = null;
    }

    if (elapsedMinutes > 0 && userId) {
      const { addAiMinutesToUser } = await import('@/lib/firebase/db');
      await addAiMinutesToUser(userId, elapsedMinutes, 2);
    }

    sessionStartedAtRef.current = null;
    setStatus('idle');
  }, [userId]);

  useEffect(() => {
    return () => { void stopSession(); };
  }, [stopSession]);

  if (!isOpen) return null;

  const statusCfg = STATUS_CONFIG[status];
  const isActive = status === 'listening' || status === 'speaking';
  const isConnecting = status === 'connecting';

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center p-2 sm:p-4 bg-black/70 backdrop-blur-xl animate-fade-in overflow-y-auto">
      <div className="relative w-full max-w-2xl apple-glass bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] rounded-3xl shadow-2xl flex flex-col my-auto max-h-[96vh] sm:max-h-[90vh] overflow-hidden animate-scale-in">

        {/* Header */}
        <div className="flex items-center justify-between p-3.5 sm:p-5 border-b border-[var(--card-border)] bg-[var(--card-bg-hover)] shrink-0">
          <div>
            <div className="flex items-center gap-2">
              <div className={`w-2.5 h-2.5 rounded-full ${
                status === 'listening' ? 'bg-rose-400 animate-pulse' :
                status === 'speaking'  ? 'bg-indigo-400 animate-pulse' :
                status === 'connecting'? 'bg-amber-400 animate-pulse' :
                status === 'ready'     ? 'bg-emerald-400' : 'bg-gray-400'
              }`} />
              <h2 className="font-black text-[var(--text-primary)] text-sm sm:text-base">🎙️ {t.tutorTitle}</h2>
              <span className="text-[9px] sm:text-[10px] font-mono bg-[var(--accent-blue)]/15 text-[var(--accent-blue)] border border-[var(--accent-blue)]/30 px-1.5 py-0.5 rounded-full truncate max-w-[120px]">
                {LIVE_MODEL.split('/')[1] || LIVE_MODEL}
              </span>
            </div>
            <p className={`text-[11px] sm:text-xs mt-0.5 font-mono ${statusCfg.color} ${statusCfg.pulse ? 'animate-pulse' : ''}`}>
              {statusCfg.label}
            </p>
          </div>

          <button onClick={() => { stopSession(); onClose(); }}
            className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] text-2xl leading-none cursor-pointer transition px-2 py-1">
            ×
          </button>
        </div>

        {/* Scrollable Body */}
        <div className="flex-1 overflow-y-auto space-y-3 p-3.5 sm:p-5 custom-scrollbar">
          {/* Visual Orb */}
          <div className="flex justify-center py-2 relative">
            <div className={`relative flex items-center justify-center w-20 h-20 sm:w-24 sm:h-24 rounded-full transition-all duration-500 ${
              status === 'listening'
                ? 'bg-rose-500/15 shadow-[0_0_50px_rgba(244,63,94,0.5)]'
                : status === 'speaking'
                ? 'bg-cyan-500/15 shadow-[0_0_50px_rgba(6,182,212,0.5)]'
                : 'bg-[var(--card-bg-hover)] border border-[var(--card-border)]'
            }`}>
              {isActive && (
                <>
                  <div className={`absolute inset-0 rounded-full border-2 animate-ping opacity-30 ${
                    status === 'listening' ? 'border-rose-400' : 'border-indigo-400'
                  }`} />
                  <div className={`absolute inset-[-6px] rounded-full border animate-pulse opacity-20 ${
                    status === 'listening' ? 'border-rose-300' : 'border-indigo-300'
                  }`} />
                </>
              )}

              <div className="text-3xl sm:text-4xl select-none">
                {status === 'listening'  ? '🎙️' :
                 status === 'speaking'   ? '🔊' :
                 status === 'connecting' ? '⏳' :
                 status === 'error'      ? '⚠️' :
                 status === 'closed'     ? '✓'  : '🎓'}
              </div>
            </div>
          </div>

          {/* Transcript Log */}
          <div ref={scrollRef} className="space-y-2.5 min-h-[100px] max-h-[220px] overflow-y-auto p-2.5 bg-[var(--card-bg-hover)] rounded-2xl border border-[var(--card-border)]">
            {messages.length === 0 && status === 'idle' && (
              <div className="text-center py-4 text-[var(--text-secondary)] text-xs">
                <p>{language === 'en' ? 'Press Start Live Call to begin talking.' : language === 'sk' ? 'Stlač Spustiť Hovor a začni rozprávať.' : 'Stiskni Spustit Hovor a začni mluvit.'}</p>
                <p className="mt-1 text-[11px] text-[var(--text-muted)]">Gemini 3.1 Flash Live</p>
              </div>
            )}
            {messages.map((m, i) => (
              <div key={i}
                className={`flex gap-2 animate-fade-up ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className="text-base shrink-0 mt-0.5">
                  {m.role === 'user' ? '🧑‍🎓' : '👩‍🏫'}
                </div>
                <div className={`px-3 py-2 rounded-2xl text-xs sm:text-sm leading-relaxed max-w-[85%] ${
                  m.role === 'user'
                    ? 'bg-emerald-500/20 border border-emerald-500/40 text-[var(--text-primary)]'
                    : 'bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)]'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
          </div>

          {/* Save Memory Notification */}
          {messages.length > 2 && (
            <div className="p-3 rounded-2xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] flex items-center justify-between gap-3 text-xs">
              <div className="flex items-center gap-2">
                <span className="text-lg">🧠</span>
                <div>
                  <div className="font-bold text-[var(--text-primary)] text-xs">
                    {language === 'en' ? 'Save conversation memory?' : language === 'sk' ? 'Uložiť pamäť konverzácie?' : 'Uložit paměť konverzace?'}
                  </div>
                  <div className="text-[11px] text-[var(--text-secondary)]">
                    {language === 'en' ? 'AI tutor will recall these facts next session.' : language === 'sk' ? 'Lektorka si zapamätá fakty pre ďalšiu reláciu.' : 'Lektorka si zapamatuje fakta pro příští lekci.'}
                  </div>
                </div>
              </div>
              <button
                onClick={async () => {
                  const userMessages = messages.filter(m => m.role === 'user').map(m => m.text);
                  const summaryText = userMessages.length > 0
                    ? userMessages.join(' | ')
                    : 'Student practiced conversation.';

                  const memObj = {
                    id: `mem_${Date.now()}`,
                    topic,
                    summary: `${topic}: "${summaryText.slice(0, 220)}"`,
                    userFacts: userMessages.slice(-4).filter(Boolean),
                    createdAt: new Date().toISOString(),
                  };

                  const targetUserId = userId || (userName === 'Lucka' ? 'user_lucka' : 'user_karel');
                  await saveTutorMemory(targetUserId, memObj);
                  setSavedMemories((prev) => [memObj, ...prev.filter((item) => item.topic !== memObj.topic || item.summary !== memObj.summary)].slice(0, 5));
                  soundEngine.playSuccessTone();
                  alert(language === 'en' ? 'Memory saved successfully!' : language === 'sk' ? 'Pamäť bola úspešne uložená!' : 'Paměť byla úspěšně uložena!');
                }}
                className="px-3.5 py-1.5 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-bold text-xs transition shrink-0 cursor-pointer shadow-sm"
              >
                💾 {t.saveMemoryBtn}
              </button>
            </div>
          )}

          {/* Error Message */}
          {errorMsg && (
            <div className="px-3 py-2 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs font-mono">
              ⚠️ {errorMsg}
            </div>
          )}

          {/* Live Coaching Buttons */}
          {isActive && (
            <div className="flex flex-wrap gap-1.5 justify-center py-1">
              <button
                onClick={() => {
                  sessionRef.current?.sendTextMessage("Help me answer please.");
                  handleTranscript('user', `💡 (${t.hintBtn})`);
                }}
                className="px-2.5 py-1.5 rounded-xl bg-amber-500/20 hover:bg-amber-500/30 border border-amber-500/40 text-amber-300 text-[11px] font-bold transition cursor-pointer flex items-center gap-1">
                <span>💡 {t.hintBtn}</span>
              </button>
              <button
                onClick={() => {
                  sessionRef.current?.sendTextMessage("Please speak slower.");
                  handleTranscript('user', `🐢 (${t.slowerBtn})`);
                }}
                className="px-2.5 py-1.5 rounded-xl bg-cyan-500/20 hover:bg-cyan-500/30 border border-cyan-500/40 text-cyan-300 text-[11px] font-bold transition cursor-pointer flex items-center gap-1">
                <span>🐢 {t.slowerBtn}</span>
              </button>
              <button
                onClick={() => {
                  sessionRef.current?.sendTextMessage("Could you repeat that please?");
                  handleTranscript('user', `🔄 (${t.repeatBtn})`);
                }}
                className="px-2.5 py-1.5 rounded-xl bg-blue-500/20 hover:bg-blue-500/30 border border-blue-500/40 text-blue-300 text-[11px] font-bold transition cursor-pointer flex items-center gap-1">
                <span>🔄 {t.repeatBtn}</span>
              </button>
            </div>
          )}

          {/* Cheat Sheet */}
          <div className="rounded-2xl border border-[var(--card-border)] bg-[var(--card-bg-hover)] p-3 space-y-1.5">
            <div className="flex items-center justify-between text-xs font-bold text-[var(--text-primary)]">
              <span className="flex items-center gap-1 text-[var(--accent-amber)] font-mono text-[10px] sm:text-[11px] uppercase tracking-wider">
                💡 {t.cheatSheetTitle} ({level})
              </span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5 text-xs">
              <div className="bg-[var(--card-bg)] border border-[var(--card-border)] p-2 rounded-xl space-y-0.5">
                <div className="text-[10px] font-mono text-[var(--accent-cyan)] font-bold">{t.sampleAnswersTitle}</div>
                <div className="font-mono text-[var(--text-primary)] text-[11px]">• Me llamo {userName || 'Karel'}.</div>
                <div className="font-mono text-[var(--text-primary)] text-[11px]">• Soy de la República Checa.</div>
              </div>
              <div className="bg-[var(--card-bg)] border border-[var(--card-border)] p-2 rounded-xl space-y-0.5">
                <div className="text-[10px] font-mono text-[var(--accent-amber)] font-bold">{t.rescuePhrasesTitle}</div>
                <div className="font-mono text-[var(--text-primary)] text-[11px]">• No entiendo.</div>
                <div className="font-mono text-[var(--text-primary)] text-[11px]">• ¿Cómo se dice...?</div>
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-3.5 sm:p-5 border-t border-[var(--card-border)] bg-[var(--card-bg-hover)] space-y-2.5 shrink-0">
          {!isActive && !isConnecting && (
            <div className="flex items-center gap-1.5 flex-wrap justify-center">
              <span className="text-[11px] text-[var(--text-secondary)] font-mono">{t.voiceLabel}</span>
              {LIVE_VOICES.map((v) => (
                <button
                  key={v.id}
                  onClick={() => {
                    soundEngine.playTick();
                    setVoiceId(v.id);
                  }}
                  className={`px-2.5 py-1 rounded-xl text-[11px] font-bold border transition cursor-pointer ${
                    voiceId === v.id
                      ? 'bg-[var(--accent-blue)] text-white border-[var(--accent-blue)]'
                      : 'bg-[var(--card-bg)] border-[var(--card-border)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                  }`}>
                  {v.id} ({v.gender === 'female' ? t.voiceFemale : t.voiceMale})
                </button>
              ))}
            </div>
          )}

          <div className="flex gap-2 justify-center">
            {status === 'idle' || status === 'closed' || status === 'error' ? (
              <button
                onClick={startSession}
                disabled={!apiKey}
                className="w-full sm:w-auto px-7 py-3 rounded-2xl bg-emerald-500 hover:bg-emerald-400 font-black text-slate-950 text-xs sm:text-sm transition cursor-pointer shadow-lg hover:scale-105 active:scale-95 disabled:opacity-40">
                ▶ {t.startCallButton}
              </button>
            ) : (
              <button
                onClick={stopSession}
                className="w-full sm:w-auto px-7 py-3 rounded-2xl bg-rose-600 hover:bg-rose-500 font-black text-white text-xs sm:text-sm transition cursor-pointer shadow-lg hover:scale-105 active:scale-95">
                ⏹ {t.endSession}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useState, useEffect } from 'react';
import { UserProfile } from '@/lib/types';
import { useAppLanguage, AppLanguage } from '@/lib/context/LanguageContext';
import { useAppTheme } from '@/lib/context/ThemeContext';
import { useActiveUser } from '@/lib/context/UserContext';
import { useLeaderboard } from '@/hooks/useLeaderboard';
import { getTranslation } from '@/lib/translations';
import ProfileManagerModal from '@/components/ProfileManagerModal';

interface NavbarProps {
  currentUser?: UserProfile;
  onSwitchUser?: (userId: string) => void;
}

export default function Navbar({ currentUser: propUser, onSwitchUser: propSwitch }: NavbarProps) {
  const pathname = usePathname();
  const { language, setLanguage } = useAppLanguage();
  const { theme, toggleTheme, setTheme } = useAppTheme();
  const { userId, profiles, setUserId, updateProfile } = useActiveUser();
  const { users } = useLeaderboard();
  const t = getTranslation(language);
  
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);

  const activeUser =
    propUser ||
    profiles.find((u) => u.uid === userId) ||
    users.find((u) => u.uid === userId) || {
      uid: userId,
      displayName: userId === 'user_karel' ? 'Karel' : 'Lucka',
      totalPoints: 0,
      currentStreak: 1,
      avatar: userId === 'user_karel' ? '👨‍💻' : '👩‍💻',
    };

  const profileOptions = profiles.length > 0 ? profiles : [activeUser];

  // Synchronizace tématu a jazyka POUZE při změně uživatele (userId)
  useEffect(() => {
    const selectedProfile = profiles.find((p) => p.uid === userId);
    if (selectedProfile) {
      if (selectedProfile.theme) {
        setTheme(selectedProfile.theme);
      }
      if (selectedProfile.preferredBaseLanguage) {
        setLanguage(selectedProfile.preferredBaseLanguage);
      }
    }
  }, [userId]); // Záměrně pouze [userId], aby se neblokovalo manuální přepínání

  // Přepnutí tématu + uložení do profilu
  const handleThemeToggle = () => {
    const nextTheme = theme === 'dark' ? 'light' : 'dark';
    toggleTheme();
    updateProfile(userId, { theme: nextTheme });
  };

  // Přepnutí jazyka + uložení do profilu
  const handleLanguageChange = (code: AppLanguage) => {
    setLanguage(code);
    updateProfile(userId, { preferredBaseLanguage: code });
  };

  const handleSelectProfile = (selectedUid: string) => {
    const selectedProfile = profiles.find((p) => p.uid === selectedUid);
    setUserId(selectedUid);
    if (selectedProfile) {
      setTheme(selectedProfile.theme || 'dark');
      setLanguage(selectedProfile.preferredBaseLanguage || 'cs');
    }
    if (typeof propSwitch === 'function') {
      propSwitch(selectedUid);
    }
    setIsProfileMenuOpen(false);
  };

  // Bezpečný render emoji i SVG avatara
  const renderAvatar = (avatarValue?: string, className = 'text-base') => {
    if (!avatarValue) return <span className={className}>👤</span>;
    if (avatarValue.startsWith('data:image') || avatarValue.startsWith('http')) {
      return (
        <img
          src={avatarValue}
          alt="Avatar"
          className="w-full h-full object-cover rounded-full"
        />
      );
    }
    return <span className={className}>{avatarValue}</span>;
  };

  const navItems = [
    { label: t.dashboard, href: '/', icon: '📊' },
    { label: t.islands, href: '/islands', icon: '🏝️' },
    { label: t.ankiDeck, href: '/anki', icon: '🧠' },
    { label: t.arena, href: '/arena', icon: '⚔️' },
    { label: t.aiTutor, href: '/tutor', icon: '🎙️' },
  ];

  const languages: { code: AppLanguage; label: string; flag: string }[] = [
    { code: 'cs', label: 'CS', flag: '🇨🇿' },
    { code: 'sk', label: 'SK', flag: '🇸🇰' },
    { code: 'en', label: 'EN', flag: '🇬🇧' },
  ];

  return (
    <>
      <header className="sticky top-0 z-[60] w-full backdrop-blur-2xl bg-[var(--nav-bg)] border-b border-[var(--nav-border)] transition-colors duration-300">
        <div className="max-w-6xl mx-auto px-3 sm:px-4 py-2.5 sm:py-3 flex items-center justify-between gap-2 sm:gap-4">
          
          {/* Logo */}
          <Link href="/" className="flex items-center space-x-1 sm:space-x-2 shrink-0 group">
            <span className="text-lg sm:text-xl font-extrabold tracking-tight text-[var(--text-primary)] group-hover:opacity-80 transition">
              Español <span className="text-[var(--accent-emerald)]">90</span>
            </span>
          </Link>

          {/* Navigace */}
          <nav className="hidden lg:flex items-center space-x-1">
            {navItems.map((item) => {
              const isActive = pathname === item.href;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={`px-3 sm:px-3.5 py-2 sm:py-1.5 rounded-full text-xs font-semibold transition-all duration-200 flex items-center space-x-1.5 min-h-[44px] lg:min-h-auto flex-col lg:flex-row text-center ${
                    isActive
                      ? 'bg-[var(--card-bg-hover)] text-[var(--text-primary)] border border-[var(--card-border-hover)] shadow-sm'
                      : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--card-bg)]'
                  }`}
                >
                  <span className="text-sm">{item.icon}</span>
                  <span className="hidden lg:inline">{item.label}</span>
                </Link>
              );
            })}
          </nav>

          {/* Ovládací prvky */}
          <div className="flex items-center gap-1 sm:gap-2">
            
            {/* Tlačítko přepnutí tématu (Světlý / Tmavý) */}
            <button
              onClick={handleThemeToggle}
              className="p-2.5 sm:p-2 rounded-full bg-[var(--card-bg)] border border-[var(--card-border)] text-xs text-[var(--text-primary)] hover:bg-[var(--card-bg-hover)] transition cursor-pointer min-h-[44px] min-w-[44px] sm:min-h-auto sm:min-w-auto flex items-center justify-center"
              title={theme === 'dark' ? t.themeLight : t.themeDark}
            >
              {theme === 'dark' ? '☀️' : '🌙'}
            </button>

            {/* Přepínač jazyků */}
            <div className="flex items-center p-0.5 bg-[var(--card-bg)] border border-[var(--card-border)] rounded-full min-h-[44px]">
              {languages.map((l) => (
                <button
                  key={l.code}
                  onClick={() => handleLanguageChange(l.code)}
                  className={`px-2 py-1.5 sm:py-1 rounded-full text-[10px] sm:text-[11px] font-bold transition flex items-center justify-center gap-1 cursor-pointer min-w-[44px] sm:min-w-auto min-h-[44px] sm:min-h-auto ${
                    language === l.code
                      ? 'bg-emerald-600 text-white font-black shadow-sm'
                      : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                  }`}
                >
                  <span>{l.flag}</span>
                  <span className="hidden sm:inline">{l.label}</span>
                </button>
              ))}
            </div>

            {/* Streak */}
            <div className="hidden sm:flex items-center space-x-1 bg-[var(--card-bg)] border border-[var(--card-border)] px-2.5 py-1 rounded-full text-[var(--accent-amber)] text-xs font-bold shrink-0 min-h-[44px]">
              <span>🔥</span>
              <span>{activeUser.currentStreak} {t.streak}</span>
            </div>

            {/* Profilové tlačítko & Dropdown */}
            <div className="relative">
              <button
                onClick={() => setIsProfileMenuOpen((prev) => !prev)}
                className="px-3 py-2.5 sm:py-1 rounded-full bg-[var(--card-bg)] border border-[var(--card-border)] text-xs font-semibold text-[var(--text-primary)] hover:bg-[var(--card-bg-hover)] transition flex items-center justify-center gap-2 cursor-pointer shrink-0 min-h-[44px] sm:min-h-auto"
                title={t.profileSwitch}
              >
                <span className="w-5 h-5 rounded-full flex items-center justify-center overflow-hidden flex-shrink-0">
                  {renderAvatar(activeUser.avatar, 'text-sm')}
                </span>
                <span className="font-bold hidden sm:inline">{activeUser.displayName}</span>
              </button>

              {isProfileMenuOpen && (
                <div className="absolute right-0 top-[calc(100%+10px)] w-64 rounded-2xl border border-[var(--card-border)] bg-[var(--card-bg)] shadow-2xl backdrop-blur-2xl z-50 overflow-hidden animate-scale-in">
                  <div className="border-b border-[var(--card-border)] px-4 py-2.5 text-[10px] font-bold uppercase tracking-[0.18em] text-[var(--text-muted)]">
                    {t.profilesTitle}
                  </div>
                  <div className="max-h-64 overflow-y-auto p-2 space-y-1 custom-scrollbar">
                    {profileOptions.map((profile) => (
                      <button
                        key={profile.uid}
                        type="button"
                        onClick={() => handleSelectProfile(profile.uid)}
                        className={`w-full flex items-center gap-3 rounded-xl p-2 text-left transition cursor-pointer ${
                          profile.uid === activeUser.uid
                            ? 'bg-[var(--accent-emerald)]/15 border border-[var(--accent-emerald)]'
                            : 'hover:bg-[var(--card-bg-hover)]'
                        }`}
                      >
                        <span className="flex h-8 w-8 items-center justify-center rounded-full bg-[var(--card-bg-hover)] text-base shrink-0 overflow-hidden border border-[var(--card-border)]">
                          {renderAvatar(profile.avatar, 'text-sm')}
                        </span>
                        <div className="min-w-0 flex-1">
                          <div className="truncate text-xs font-bold text-[var(--text-primary)]">
                            {profile.displayName}
                          </div>
                          <div className="text-[9px] uppercase tracking-wider text-[var(--text-muted)] font-mono">
                            {profile.startingLevel || 'A1'} • {profile.preferredBaseLanguage || 'CS'}
                          </div>
                        </div>
                      </button>
                    ))}
                  </div>
                  <button
                    type="button"
                    onClick={() => {
                      setIsProfileMenuOpen(false);
                      setIsProfileModalOpen(true);
                    }}
                    className="w-full border-t border-[var(--card-border)] bg-[var(--card-bg-hover)] hover:bg-white/10 px-4 py-2.5 text-left text-xs font-bold text-[var(--text-primary)] transition cursor-pointer flex items-center gap-2"
                  >
                    <span>{t.manageProfiles}</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      <ProfileManagerModal
        isOpen={isProfileModalOpen}
        onClose={() => setIsProfileModalOpen(false)}
      />

      {/* Mobilní spodní lišta */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 z-50 bg-[var(--nav-bg)] backdrop-blur-2xl border-t border-[var(--nav-border)] px-3 py-2 flex items-center justify-around shadow-2xl">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`flex flex-col items-center justify-center py-1 px-3 rounded-2xl transition cursor-pointer ${
                isActive
                  ? 'text-[var(--accent-emerald)] font-bold bg-[var(--card-bg-hover)]'
                  : 'text-[var(--text-muted)] font-medium hover:text-[var(--text-primary)]'
              }`}
            >
              <span className="text-xl mb-0.5">{item.icon}</span>
              <span className="text-[10px] tracking-tight">{item.label}</span>
            </Link>
          );
        })}
      </div>
    </>
  );
}

'use client';

import { FormEvent, useEffect, useMemo, useState } from 'react';
import { useActiveUser } from '@/lib/context/UserContext';
import { useAppTheme } from '@/lib/context/ThemeContext';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';
import { AppTheme, CEFRLevel, PreferredBaseLanguage } from '@/lib/types';
import { soundEngine } from '@/lib/audio/sound-engine';
import AvatarGeneratorModal from '@/components/AvatarGeneratorModal';

const LEVEL_OPTIONS: CEFRLevel[] = ['A0', 'A1', 'A2', 'B1', 'B2', 'C1', 'C2'];
const AVATAR_OPTIONS = [
  '👨‍💻', '👩‍💻', '🧑‍🎓', '💃', '🐂', '🥘', '🎸', '👑',
  '🧑‍🚀', '👩‍🎨', '🧑‍🏫', '🧑‍🍳', '🤠', '🤓', '🔥', '🌴'
];

interface ProfileManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function ProfileManagerModal({ isOpen, onClose }: ProfileManagerModalProps) {
  const { profiles, userId, setUserId, createProfile, updateProfile, deleteProfile } = useActiveUser();
  const { theme: activeTheme, setTheme } = useAppTheme();
  const { language, setLanguage } = useAppLanguage();
  const t = getTranslation(language);

  const LANGUAGE_OPTIONS: { value: PreferredBaseLanguage; label: string; flag: string }[] = [
    { value: 'cs', label: 'Čeština', flag: '🇨🇿' },
    { value: 'sk', label: 'Slovenčina', flag: '🇸🇰' },
    { value: 'en', label: 'English', flag: '🇬🇧' },
  ];

  const THEME_OPTIONS: { value: AppTheme; label: string; icon: string }[] = [
    { value: 'dark', label: t.themeDark, icon: '🌙' },
    { value: 'light', label: t.themeLight, icon: '☀️' },
  ];

  // Výchozí editace je aktuálně přihlášený uživatel
  const [editingUid, setEditingUid] = useState<string | null>(userId);
  const [name, setName] = useState('');
  const [avatar, setAvatar] = useState('👤');
  const [theme, setThemeValue] = useState<AppTheme>('dark');
  const [preferredBaseLanguage, setPreferredBaseLanguage] = useState<PreferredBaseLanguage>('cs');
  const [startingLevel, setStartingLevel] = useState<CEFRLevel>('A1');
  const [isAvatarModalOpen, setIsAvatarModalOpen] = useState(false);

  const activeProfile = useMemo(
    () => profiles.find((profile) => profile.uid === (editingUid || userId)) || profiles[0],
    [profiles, userId, editingUid]
  );

  useEffect(() => {
    if (!isOpen) return;

    if (editingUid && editingUid !== 'new') {
      const selectedProfile = profiles.find((profile) => profile.uid === editingUid);
      if (selectedProfile) {
        setName(selectedProfile.displayName || '');
        setAvatar(selectedProfile.avatar || '👤');
        setThemeValue(selectedProfile.theme || 'dark');
        setPreferredBaseLanguage(selectedProfile.preferredBaseLanguage || selectedProfile.nativeLanguage || 'cs');
        setStartingLevel(selectedProfile.startingLevel || selectedProfile.level || 'A1');
        return;
      }
    }

    if (editingUid === 'new') {
      setName('');
      setAvatar('💃');
      setThemeValue('dark');
      setPreferredBaseLanguage(language);
      setStartingLevel('A1');
      return;
    }

    const source = activeProfile || profiles[0];
    setName(source?.displayName || '');
    setAvatar(source?.avatar || '👤');
    setThemeValue(source?.theme || 'dark');
    setPreferredBaseLanguage(source?.preferredBaseLanguage || source?.nativeLanguage || 'cs');
    setStartingLevel(source?.startingLevel || source?.level || 'A1');
  }, [isOpen, activeProfile, editingUid, profiles, language]);

  if (!isOpen) return null;

  const handleProfileSelect = (uid: string) => {
    soundEngine.playTick();
    setUserId(uid);
    setEditingUid(uid);
    const selectedProfile = profiles.find((profile) => profile.uid === uid);
    if (selectedProfile) {
      setName(selectedProfile.displayName || '');
      setAvatar(selectedProfile.avatar || '👤');
      setThemeValue(selectedProfile.theme || 'dark');
      setPreferredBaseLanguage(selectedProfile.preferredBaseLanguage || selectedProfile.nativeLanguage || 'cs');
      setStartingLevel(selectedProfile.startingLevel || selectedProfile.level || 'A1');
      setTheme(selectedProfile.theme || 'dark');
      setLanguage(selectedProfile.preferredBaseLanguage || selectedProfile.nativeLanguage || 'cs');
    }
  };

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();

    const cleanedName = name.trim();
    if (!cleanedName) return;

    soundEngine.playTick();

    if (editingUid && editingUid !== 'new') {
      updateProfile(editingUid, {
        displayName: cleanedName,
        avatar,
        theme,
        preferredBaseLanguage,
        startingLevel,
      });
      setUserId(editingUid);
      setTheme(theme);
      setLanguage(preferredBaseLanguage);
    } else {
      const created = createProfile({
        displayName: cleanedName,
        avatar,
        theme,
        preferredBaseLanguage,
        startingLevel,
      });
      setUserId(created.uid);
      setTheme(theme);
      setLanguage(preferredBaseLanguage);
      setEditingUid(created.uid);
    }

    onClose();
  };

  const handleDelete = (uid: string) => {
    if (uid === 'user_karel' || uid === 'user_lucka') return;
    if (!confirm(t.deleteProfileConfirm)) return;

    soundEngine.playUntick();
    deleteProfile(uid);
    if (userId === uid) {
      const fallback = profiles.find((profile) => profile.uid !== uid) || profiles[0];
      if (fallback) {
        setUserId(fallback.uid);
        setEditingUid(fallback.uid);
      }
    }
  };

  const renderAvatarContent = (avatarValue?: string, className = 'text-lg') => {
    if (!avatarValue) return <span className={className}>👤</span>;
    if (avatarValue.startsWith('data:image') || avatarValue.startsWith('http')) {
      return (
        <img
          src={avatarValue}
          alt="Avatar"
          className="w-full h-full object-cover rounded-full"
        />
      );
    }
    return <span className={className}>{avatarValue}</span>;
  };

  const isCustomSvgAvatar = Boolean(
    avatar && (avatar.startsWith('data:image') || avatar.startsWith('http'))
  );

  const isCreatingNew = editingUid === 'new';

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-2 sm:p-4 bg-black/70 backdrop-blur-xl animate-fade-in overflow-hidden">
      <div className="relative w-full max-w-4xl max-h-[94vh] sm:max-h-[90vh] bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] rounded-3xl shadow-2xl backdrop-blur-2xl flex flex-col overflow-hidden animate-scale-in">
        
        {/* ── 1. Top Fixed Header ── */}
        <div className="flex items-center justify-between border-b border-[var(--card-border)] px-5 sm:px-7 py-4 bg-[var(--card-bg-hover)] shrink-0">
          <div>
            <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-[var(--text-muted)] font-mono">
              {t.profilesTitle}
            </p>
            <h2 className="text-lg sm:text-xl font-extrabold text-[var(--text-primary)]">
              {isCreatingNew ? t.addProfile : `${t.editProfile} — ${name || activeProfile?.displayName}`}
            </h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="w-8 h-8 rounded-full bg-[var(--card-bg)] border border-[var(--card-border)] text-sm font-bold text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--card-bg-hover)] transition flex items-center justify-center cursor-pointer"
          >
            ✕
          </button>
        </div>

        {/* ── 2. Scrollable Body Content ── */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-6 md:p-8 custom-scrollbar">
          <div className="grid gap-6 md:grid-cols-[240px_minmax(0,1fr)]">
            
            {/* Left: Profiles List & Add Button */}
            <div className="space-y-3">
              <button
                type="button"
                onClick={() => {
                  soundEngine.playTick();
                  setEditingUid('new');
                }}
                className={`w-full rounded-2xl border-2 border-dashed px-4 py-3 text-xs font-black transition flex items-center justify-center gap-1.5 cursor-pointer shadow-sm ${
                  isCreatingNew
                    ? 'border-emerald-500 bg-emerald-500/20 text-emerald-400'
                    : 'border-[var(--accent-emerald)]/50 bg-[var(--accent-emerald)]/10 text-[var(--accent-emerald)] hover:bg-[var(--accent-emerald)]/20'
                }`}
              >
                <span>{t.addProfile}</span>
              </button>

              <div className="space-y-2 max-h-48 md:max-h-none overflow-y-auto pr-1">
                {profiles.map((profile) => {
                  const isSelected = !isCreatingNew && (editingUid ? editingUid === profile.uid : userId === profile.uid);
                  return (
                    <div
                      key={profile.uid}
                      className={`flex items-center justify-between rounded-2xl border p-2.5 transition ${
                        isSelected
                          ? 'border-[var(--accent-emerald)] bg-[var(--accent-emerald)]/15 shadow-sm'
                          : 'border-[var(--card-border)] bg-[var(--card-bg-hover)] hover:border-white/20'
                      }`}
                    >
                      <button
                        type="button"
                        onClick={() => handleProfileSelect(profile.uid)}
                        className="flex-1 text-left flex items-center gap-2.5 min-w-0 cursor-pointer"
                      >
                        <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--card-bg)] text-lg shrink-0 border border-[var(--card-border)] overflow-hidden">
                          {renderAvatarContent(profile.avatar, 'text-base')}
                        </span>
                        <div className="min-w-0 flex-1">
                          <div className="text-xs font-bold text-[var(--text-primary)] truncate">
                            {profile.displayName}
                          </div>
                          <div className="text-[9px] uppercase tracking-wider text-[var(--text-muted)] font-mono">
                            {profile.startingLevel || 'A1'} • {profile.preferredBaseLanguage || 'CS'}
                          </div>
                        </div>
                      </button>

                      <button
                        type="button"
                        onClick={() => {
                          soundEngine.playTick();
                          setEditingUid(profile.uid);
                        }}
                        className="ml-1.5 px-2 py-1 rounded-lg text-[10px] font-bold bg-[var(--card-bg)] hover:bg-[var(--card-bg-hover)] text-[var(--text-secondary)] border border-[var(--card-border)] shrink-0 cursor-pointer"
                      >
                        ✏️
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Right: Profile Details Form */}
            <form id="profile-edit-form" onSubmit={handleSubmit} className="space-y-5">
              {/* Name input */}
              <div>
                <label className="mb-1.5 block text-xs font-bold uppercase tracking-wider text-[var(--text-muted)]">
                  {t.profileName} *
                </label>
                <input
                  type="text"
                  required
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  placeholder={t.profileNamePlaceholder}
                  className="w-full rounded-2xl border border-[var(--card-border)] bg-[var(--card-bg-hover)] px-4 py-2.5 text-sm text-[var(--text-primary)] outline-none focus:border-[var(--accent-emerald)] transition"
                />
              </div>

              {/* Avatar Selector + AI Generator */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <label className="block text-xs font-bold uppercase tracking-wider text-[var(--text-muted)]">
                    {t.avatar}
                  </label>
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-mono font-bold text-[var(--accent-emerald)]">
                      {t.activeAvatarLabel}
                    </span>
                    <div className="w-7 h-7 rounded-full bg-[var(--card-bg-hover)] border border-[var(--card-border)] flex items-center justify-center overflow-hidden">
                      {renderAvatarContent(avatar, 'text-sm')}
                    </div>
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() => {
                    soundEngine.playTick();
                    setIsAvatarModalOpen(true);
                  }}
                  className="w-full py-2.5 px-4 rounded-2xl border-2 border-dashed border-[var(--accent-emerald)]/50 bg-[var(--accent-emerald)]/10 hover:bg-[var(--accent-emerald)]/20 text-xs font-extrabold text-[var(--accent-emerald)] transition flex items-center justify-center gap-2 cursor-pointer shadow-sm hover:scale-[1.01]"
                >
                  <span>✨ {t.generateAiAvatar}</span>
                </button>

                {isCustomSvgAvatar && (
                  <div className="p-3 bg-[var(--card-bg-hover)] border border-[var(--accent-emerald)]/40 rounded-2xl flex items-center justify-between gap-3">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full border border-[var(--accent-emerald)] overflow-hidden bg-black p-0.5">
                        <img src={avatar} alt="Custom AI Avatar" className="w-full h-full object-cover rounded-full" />
                      </div>
                      <div className="text-xs">
                        <p className="font-bold text-[var(--text-primary)]">Custom AI Avatar active</p>
                        <p className="text-[10px] text-[var(--text-secondary)]">Generated via Gemini AI</p>
                      </div>
                    </div>
                    <button
                      type="button"
                      onClick={() => setAvatar('👨‍💻')}
                      className="text-[11px] text-[var(--text-secondary)] hover:text-rose-400 font-medium underline cursor-pointer"
                    >
                      Emoji
                    </button>
                  </div>
                )}

                <div className="grid grid-cols-8 gap-2 bg-[var(--card-bg-hover)] p-2.5 rounded-2xl border border-[var(--card-border)]">
                  {AVATAR_OPTIONS.map((option) => (
                    <button
                      key={option}
                      type="button"
                      onClick={() => {
                        soundEngine.playTick();
                        setAvatar(option);
                      }}
                      className={`h-10 w-full flex items-center justify-center rounded-xl text-lg transition cursor-pointer ${
                        avatar === option
                          ? 'bg-[var(--accent-emerald)] text-black font-extrabold shadow-md scale-110'
                          : 'hover:bg-white/10 text-[var(--text-primary)]'
                      }`}
                    >
                      {option}
                    </button>
                  ))}
                </div>
              </div>

              {/* Language & Theme Grid */}
              <div className="grid gap-4 sm:grid-cols-2">
                <div>
                  <label className="mb-1.5 block text-xs font-bold uppercase tracking-wider text-[var(--text-muted)]">
                    {t.preferredBaseLanguage}
                  </label>
                  <div className="grid grid-cols-3 gap-1.5">
                    {LANGUAGE_OPTIONS.map((option) => (
                      <button
                        key={option.value}
                        type="button"
                        onClick={() => {
                          soundEngine.playTick();
                          setPreferredBaseLanguage(option.value);
                        }}
                        className={`rounded-xl border py-2 px-1 text-xs font-bold transition flex items-center justify-center gap-1 cursor-pointer ${
                          preferredBaseLanguage === option.value
                            ? 'border-[var(--accent-emerald)] bg-[var(--accent-emerald)]/15 text-[var(--text-primary)] shadow-sm'
                            : 'border-[var(--card-border)] bg-[var(--card-bg)] text-[var(--text-secondary)] hover:bg-[var(--card-bg-hover)]'
                        }`}
                      >
                        <span>{option.flag}</span>
                        <span className="truncate">{option.label}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="mb-1.5 block text-xs font-bold uppercase tracking-wider text-[var(--text-muted)]">
                    {t.theme}
                  </label>
                  <div className="grid grid-cols-2 gap-1.5">
                    {THEME_OPTIONS.map((option) => (
                      <button
                        key={option.value}
                        type="button"
                        onClick={() => {
                          soundEngine.playTick();
                          setThemeValue(option.value);
                        }}
                        className={`rounded-xl border py-2 px-2 text-xs font-bold transition flex items-center justify-center gap-1.5 cursor-pointer ${
                          theme === option.value
                            ? 'border-[var(--accent-emerald)] bg-[var(--accent-emerald)]/15 text-[var(--text-primary)] shadow-sm'
                            : 'border-[var(--card-border)] bg-[var(--card-bg)] text-[var(--text-secondary)] hover:bg-[var(--card-bg-hover)]'
                        }`}
                      >
                        <span>{option.icon}</span>
                        <span>{option.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {/* CEFR Level Selection */}
              <div>
                <label className="mb-1.5 block text-xs font-bold uppercase tracking-wider text-[var(--text-muted)]">
                  {t.startingLevel}
                </label>
                <div className="grid grid-cols-4 sm:grid-cols-7 gap-1.5">
                  {LEVEL_OPTIONS.map((level) => (
                    <button
                      key={level}
                      type="button"
                      onClick={() => {
                        soundEngine.playTick();
                        setStartingLevel(level);
                      }}
                      className={`rounded-xl border py-2 text-xs font-extrabold transition cursor-pointer ${
                        startingLevel === level
                          ? 'border-[var(--accent-emerald)] bg-[var(--accent-emerald)]/20 text-[var(--accent-emerald)] shadow-sm'
                          : 'border-[var(--card-border)] bg-[var(--card-bg)] text-[var(--text-secondary)] hover:bg-[var(--card-bg-hover)]'
                      }`}
                    >
                      {level}
                    </button>
                  ))}
                </div>
              </div>
            </form>
          </div>
        </div>

        {/* ── 3. Bottom Sticky Action Bar (Vysoce kontrastní tlačítka) ── */}
        <div className="border-t border-[var(--card-border)] px-5 sm:px-7 py-3.5 bg-[var(--card-bg-hover)] flex items-center justify-between gap-3 shrink-0">
          <div>
            {!isCreatingNew && editingUid !== 'user_karel' && editingUid !== 'user_lucka' && (
              <button
                type="button"
                onClick={() => editingUid && handleDelete(editingUid)}
                className="px-3.5 py-2 rounded-xl bg-rose-500/15 hover:bg-rose-500/25 text-rose-400 border border-rose-500/30 text-xs font-bold transition cursor-pointer"
              >
                🗑️ {t.delete}
              </button>
            )}
          </div>

          <div className="flex items-center gap-2.5">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 rounded-full bg-[var(--card-bg)] border border-[var(--card-border)] text-xs font-bold text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--card-bg-hover)] transition cursor-pointer"
            >
              {t.cancel}
            </button>
            <button
              type="submit"
              form="profile-edit-form"
              className="px-6 py-2.5 rounded-full bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-black text-xs transition cursor-pointer shadow-lg hover:scale-105 active:scale-95"
            >
              {isCreatingNew ? `+ ${t.create}` : `✓ ${t.save}`}
            </button>
          </div>
        </div>

      </div>

      <AvatarGeneratorModal
        isOpen={isAvatarModalOpen}
        onClose={() => setIsAvatarModalOpen(false)}
        userName={name || 'Amigo'}
        onAvatarGenerated={(svgDataUri) => setAvatar(svgDataUri)}
      />
    </div>
  );
}

'use client';

import { motion } from 'framer-motion';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';

interface ProgressRingProps {
  currentDay: number; // 1 to 90
  totalDays?: number;
  size?: number;
  strokeWidth?: number;
}

export default function ProgressRing({
  currentDay,
  totalDays = 90,
  size = 150,
  strokeWidth = 10,
}: ProgressRingProps) {
  const { language } = useAppLanguage();
  const t = getTranslation(language);

  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const percentage = Math.min(100, Math.max(0, (currentDay / totalDays) * 100));
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div className="relative flex items-center justify-center shrink-0" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="transform -rotate-90">
        {/* Background Track */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="var(--card-border)"
          strokeWidth={strokeWidth}
          fill="transparent"
        />
        {/* Animated Progress Ring */}
        <motion.circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="url(#gradientRing)"
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          initial={{ strokeDashoffset: circumference }}
          animate={{ strokeDashoffset }}
          transition={{ duration: 1.4, ease: [0.16, 1, 0.3, 1] }}
          strokeLinecap="round"
          fill="transparent"
        />
        <defs>
          <linearGradient id="gradientRing" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="var(--accent-emerald)" />
            <stop offset="100%" stopColor="var(--accent-cyan)" />
          </linearGradient>
        </defs>
      </svg>
      {/* Center Text */}
      <div className="absolute text-center">
        <span className="text-4xl font-extrabold text-[var(--text-primary)] tracking-tight block leading-none">
          {currentDay}
        </span>
        <span className="text-[11px] text-[var(--text-secondary)] font-semibold mt-1 block">
          / {totalDays} {t.daysCount}
        </span>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { soundEngine } from '@/lib/audio/sound-engine';
import confetti from 'canvas-confetti';

interface QuizQuestion {
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

interface QuizModalProps {
  isOpen: boolean;
  onClose: () => void;
  onCompleteQuiz: (bonusPoints: number) => void;
}

export default function QuizModal({ isOpen, onClose, onCompleteQuiz }: QuizModalProps) {
  const [quiz, setQuiz] = useState<QuizQuestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [finished, setFinished] = useState(false);

  const fetchQuiz = async () => {
    setLoading(true);
    setFinished(false);
    setCurrentIndex(0);
    setScore(0);
    setSelectedOption(null);

    try {
      const res = await fetch('/api/ai/quiz', { method: 'POST' });
      const data = await res.json();
      if (data.quiz) setQuiz(data.quiz);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectOption = (idx: number) => {
    if (selectedOption !== null) return;
    setSelectedOption(idx);

    const isCorrect = idx === quiz[currentIndex].correctIndex;
    if (isCorrect) {
      soundEngine.playTick();
      setScore((s) => s + 1);
    } else {
      soundEngine.playUntick();
    }

    setTimeout(() => {
      if (currentIndex + 1 < quiz.length) {
        setCurrentIndex((c) => c + 1);
        setSelectedOption(null);
      } else {
        setFinished(true);
        const finalScore = score + (isCorrect ? 1 : 0);
        const bonus = finalScore * 5;
        if (bonus > 0) {
          soundEngine.playVictoryFanfare();
          try {
            confetti({ particleCount: 70, spread: 60, origin: { y: 0.6 } });
          } catch {
            // ignore
          }
        }
        onCompleteQuiz(bonus);
      }
    }, 1200);
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-md">
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.95 }}
          className="apple-glass w-full max-w-lg p-6 relative bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] shadow-2xl"
        >
          <button
            onClick={onClose}
            className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)] cursor-pointer w-8 h-8 rounded-full bg-[var(--card-bg-hover)] border border-[var(--card-border)] flex items-center justify-center transition"
          >
            ✕
          </button>

          {quiz.length === 0 && !loading && (
            <div className="text-center py-8 space-y-4">
              <span className="text-5xl">⚡</span>
              <h2 className="text-2xl font-bold text-[var(--text-primary)]">Daily Speed Quiz</h2>
              <p className="text-[var(--text-secondary)] text-sm">
                Answer 3 questions generated by Gemini Lite to earn up to +15 bonus points!
              </p>
              <button
                onClick={fetchQuiz}
                className="px-6 py-3 rounded-2xl bg-emerald-500 font-bold text-slate-950 hover:bg-emerald-400 transition cursor-pointer"
              >
                Start Quiz
              </button>
            </div>
          )}

          {loading && (
            <div className="text-center py-12 space-y-3">
              <div className="animate-spin w-8 h-8 border-4 border-emerald-400 border-t-transparent rounded-full mx-auto" />
              <p className="text-sm font-mono text-emerald-300">Generating AI Quiz (Gemini Lite)...</p>
            </div>
          )}

          {quiz.length > 0 && !finished && !loading && (
            <div className="space-y-6">
              <div className="flex justify-between items-center text-xs font-mono text-slate-400">
                <span>
                  Question {currentIndex + 1} of {quiz.length}
                </span>
                <span>Current Bonus: {score * 5} pts</span>
              </div>
              <h3 className="text-lg font-bold text-[var(--text-primary)]">{quiz[currentIndex].question}</h3>
              <div className="space-y-3">
                {quiz[currentIndex].options.map((opt, idx) => {
                  let btnStyle = 'glass-panel-interactive text-[var(--text-primary)]';
                  if (selectedOption !== null) {
                    if (idx === quiz[currentIndex].correctIndex)
                      btnStyle =
                        'bg-emerald-500/20 border-emerald-500 text-emerald-300 shadow-[0_0_15px_rgba(16,185,129,0.3)]';
                    else if (idx === selectedOption)
                      btnStyle = 'bg-rose-500/20 border-rose-500 text-rose-300';
                  }
                  return (
                    <button
                      key={idx}
                      onClick={() => handleSelectOption(idx)}
                      disabled={selectedOption !== null}
                      className={`w-full p-4 rounded-2xl text-left font-medium transition cursor-pointer ${btnStyle}`}
                    >
                      {opt}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {finished && (
            <div className="text-center py-8 space-y-4">
              <span className="text-5xl">🏆</span>
              <h2 className="text-2xl font-bold text-[var(--text-primary)]">Quiz Completed!</h2>
              <p className="text-emerald-400 font-bold text-lg">
                +{score * 5} Bonus Points Earned
              </p>
              <button
                onClick={onClose}
                className="px-6 py-2.5 rounded-2xl bg-white/10 hover:bg-white/20 font-semibold text-sm cursor-pointer"
              >
                Close
              </button>
            </div>
          )}
        </motion.div>
      </div>
    </AnimatePresence>
  );
}

'use client';

import { motion, useInView } from 'framer-motion';
import { useRef, ReactNode } from 'react';

interface ScrollRevealProps {
  children: ReactNode;
  animation?: 'fade-up' | 'fade-in' | 'scale-in' | 'slide-left' | 'slide-right';
  delay?: number;
  duration?: number;
  className?: string;
  once?: boolean;
}

export default function ScrollReveal({
  children,
  animation = 'fade-up',
  delay = 0,
  duration = 0.7,
  className = '',
  once = true,
}: ScrollRevealProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once, margin: '-50px' });

  const getVariants = () => {
    switch (animation) {
      case 'fade-up':
        return {
          hidden: { opacity: 0, y: 35 },
          visible: { opacity: 1, y: 0 },
        };
      case 'fade-in':
        return {
          hidden: { opacity: 0 },
          visible: { opacity: 1 },
        };
      case 'scale-in':
        return {
          hidden: { opacity: 0, scale: 0.92 },
          visible: { opacity: 1, scale: 1 },
        };
      case 'slide-left':
        return {
          hidden: { opacity: 0, x: 40 },
          visible: { opacity: 1, x: 0 },
        };
      case 'slide-right':
        return {
          hidden: { opacity: 0, x: -40 },
          visible: { opacity: 1, x: 0 },
        };
      default:
        return {
          hidden: { opacity: 0, y: 35 },
          visible: { opacity: 1, y: 0 },
        };
    }
  };

  return (
    <motion.div
      ref={ref}
      initial="hidden"
      animate={isInView ? 'visible' : 'hidden'}
      variants={getVariants()}
      transition={{
        duration,
        delay,
        ease: [0.16, 1, 0.3, 1], // Smooth Apple-style cubic-bezier
      }}
      className={className}
    >
      {children}
    </motion.div>
  );
}

'use client';

import { motion } from 'framer-motion';
import Link from 'next/link';

interface TaskCardProps {
  id: string;
  title: string;
  duration: string;
  icon: string;
  completed: boolean;
  onToggle: (id: string) => void;
  actionHref?: string;
  actionLabel?: string;
  onActionClick?: () => void;
}

export default function TaskCard({
  id,
  title,
  duration,
  icon,
  completed,
  onToggle,
  actionHref,
  actionLabel,
  onActionClick,
}: TaskCardProps) {
  return (
    <motion.div
      whileHover={{ y: -3, scale: 1.005 }}
      transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }}
      className={`w-full p-4 sm:p-5 rounded-3xl border text-left transition-all duration-300 flex flex-col sm:flex-row sm:items-center justify-between gap-3 sm:gap-4 ${
        completed
          ? 'bg-[var(--card-bg)] border-[var(--accent-emerald)]/40 shadow-sm'
          : 'apple-card-interactive'
      }`}
    >
      <div className="flex items-center space-x-3 sm:space-x-4 flex-1">
        <div
          onClick={() => onToggle(id)}
          className={`w-14 h-14 sm:w-12 sm:h-12 rounded-2xl flex items-center justify-center text-2xl transition-colors cursor-pointer shrink-0 ${
            completed
              ? 'bg-[var(--accent-emerald)]/15 text-[var(--accent-emerald)]'
              : 'bg-[var(--card-bg)] text-[var(--text-secondary)] border border-[var(--card-border)]'
          }`}
          aria-label={title}
        >
          {icon}
        </div>
        <div className="flex-1 min-w-0">
          <h3
            onClick={() => onToggle(id)}
            className={`font-bold text-sm sm:text-base transition-colors cursor-pointer ${
              completed ? 'text-[var(--accent-emerald)]' : 'text-[var(--text-primary)]'
            }`}
          >
            {title}
          </h3>
          <p className="text-xs text-[var(--text-secondary)] font-medium mt-1 line-clamp-2 sm:line-clamp-1">{duration}</p>
        </div>
      </div>

      <div className="flex items-center gap-2 sm:gap-3 justify-between sm:justify-end w-full sm:w-auto">
        {(actionHref || actionLabel || onActionClick) && (
          actionHref ? (
            <Link
              href={actionHref}
              className="flex-1 sm:flex-none px-3 sm:px-4 py-2.5 sm:py-2 rounded-full bg-[var(--card-bg)] hover:bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[var(--text-primary)] text-xs font-bold transition cursor-pointer flex items-center justify-center gap-1.5 shadow-sm min-h-[44px] sm:min-h-auto"
            >
              <span>🚀</span> <span className="hidden sm:inline">{actionLabel || 'Spustit'}</span>
            </Link>
          ) : (
            <button
              onClick={onActionClick}
              className="flex-1 sm:flex-none px-3 sm:px-4 py-2.5 sm:py-2 rounded-full bg-[var(--card-bg)] hover:bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[var(--text-primary)] text-xs font-bold transition cursor-pointer flex items-center justify-center gap-1.5 shadow-sm min-h-[44px] sm:min-h-auto"
            >
              <span>🚀</span> <span className="hidden sm:inline">{actionLabel || 'Otevřít'}</span>
            </button>
          )
        )}

        <button
          onClick={() => onToggle(id)}
          className={`w-11 h-11 sm:w-9 sm:h-9 rounded-full border flex items-center justify-center transition-all cursor-pointer flex-shrink-0 ${
            completed
              ? 'bg-[var(--accent-emerald)] border-[var(--accent-emerald)] text-black font-extrabold shadow-md'
              : 'border-[var(--card-border)] bg-[var(--card-bg)] hover:border-[var(--card-border-hover)] text-[var(--text-muted)]'
          }`}
          title={completed ? 'Hotovo (kliknutím zrušíš)' : 'Označit jako hotové'}
        >
          {completed ? <span className="text-base sm:text-sm">✓</span> : <span className="text-sm">○</span>}
        </button>
      </div>
    </motion.div>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { LiveTutorSession, LiveStatus, LIVE_MODEL, LIVE_VOICES } from '@/lib/ai/live-session';
import { BookLessonDetail } from '@/lib/data/book-curriculum';
import { getProkopovaLessonData } from '@/lib/data/prokopova-book-data';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';
import { soundEngine } from '@/lib/audio/sound-engine';

interface TextbookLiveModalProps {
  isOpen: boolean;
  onClose: () => void;
  bookMeta: BookLessonDetail;
  userName?: string;
  userId?: string;
}

export default function TextbookLiveModal({
  isOpen,
  onClose,
  bookMeta,
  userName = 'Karel',
  userId,
}: TextbookLiveModalProps) {
  const { language } = useAppLanguage();
  const t = getTranslation(language);

  const [status, setStatus] = useState<LiveStatus>('idle');
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [voiceId, setVoiceId] = useState<(typeof LIVE_VOICES)[number]['id']>('Aoede');
  
  const sessionRef = useRef<LiveTutorSession | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const apiKey = process.env.NEXT_PUBLIC_GEMINI_API_KEY || '';

  const isEn = language === 'en';
  const isSk = language === 'sk';
  const langLabel = isSk ? 'slovenčine' : isEn ? 'English' : 'češtine';

  const STATUS_CONFIG: Record<LiveStatus, { label: string; color: string; pulse: boolean }> = {
    idle:       { label: t.idleStatus,        color: 'text-[var(--text-secondary)]', pulse: false },
    connecting: { label: t.connectingStatus,  color: 'text-amber-400',               pulse: true  },
    ready:      { label: t.ready,             color: 'text-emerald-400',             pulse: false },
    listening:  { label: t.listeningStatus,  color: 'text-rose-400',                pulse: true  },
    speaking:   { label: t.speakingStatus,   color: 'text-cyan-400',                pulse: true  },
    error:      { label: t.error,             color: 'text-rose-400',                pulse: false },
    closed:     { label: t.close,             color: 'text-[var(--text-secondary)]', pulse: false },
  };

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    return () => { sessionRef.current?.disconnect(); };
  }, []);

  const handleTranscript = useCallback((role: 'user' | 'model', text: string) => {
    setMessages((prev) => {
      if (prev.length > 0 && prev[prev.length - 1].role === role) {
        const updated = [...prev];
        updated[updated.length - 1] = { ...updated[updated.length - 1], text: updated[updated.length - 1].text + ' ' + text };
        return updated;
      }
      return [...prev, { role, text }];
    });
  }, []);

  // Načtení detailních doslovných dat lekce z knihy
  const rawLessonData = getProkopovaLessonData(bookMeta.lessonNumber);

  // Příprava doslovného textu dialogů z knihy do promptu
  const dialogueContext = rawLessonData?.texts?.map(t => {
    if (t.type === 'dialogue' && t.speakers) {
      return t.speakers.map(s => `${s.speaker}: "${s.text}"`).join('\n');
    }
    if (t.content) {
      return Array.isArray(t.content) ? t.content.join('\n') : t.content;
    }
    return '';
  }).join('\n\n') || 'Úvodní text/dialog lekce';

  // Příprava slovní zásoby z knihy
  const vocabContext = rawLessonData?.vocabulary?.slice(0, 40).map(v => `${v.es} (${v.cs})`).join(', ') || '';

  // Příprava gramatických bodů
  const grammarContext = rawLessonData?.grammar?.map(g => {
    const rules = g.rules ? g.rules.join('; ') : '';
    return `[${g.roman_numeral || g.topic || '•'} ${g.title || ''}]: ${rules}`;
  }).join('\n') || bookMeta.grammarTopics.join(', ');

  // Příprava seznamu cvičení a doporučení k přeskočení
  const exercisesContext = rawLessonData?.exercises?.map(e => `Cvičení ${e.number} (${e.type}): ${e.instruction}`).join('\n') || '';

  // ── NEPRŮSTŘELNÝ UČITELSKÝ PROMPT S DOSLOVNÝM OBSAHEM KNIHY ──
  const textbookSystemPrompt = `
Jsi osobní lektorka španělštiny (Lektorka Elena).
Sedíš se studentem (${userName}) a máte před sebou OTEVŘENOU učebnici "Španělština pro samouky" od Lídy Prokopové.

MÁŠ PŘED SEBOU PŘESNÝ OBSAH TÉTO LEKCE:
📖 LEKCE ${bookMeta.lessonNumber}: "${bookMeta.title}" (${bookMeta.pages})

1. DOSLOVNÝ TEXT / DIALOGY V TÉTO LEKCI:
"""
${dialogueContext}
"""

2. SLOVNÍ ZÁSOBA TÉTO LEKCE:
${vocabContext}

3. GRAMATICKÁ PRAVIDLA V TÉTO LEKCI:
${grammarContext}

4. CVIČENÍ V KNIZE:
${exercisesContext || 'Písemná doplňovací cvičení'}

5. METODICKÉ POKYNY:
- Co má student v knize projít: "${bookMeta.whatToStudy}"
- CO MÁ STUDENT ROZHODNĚ PŘESKOČIT: "${bookMeta.whatToSkip}"
- Zlaté pravidlo: "${bookMeta.keyRuleTip}"

STRIKTNÍ PRAVIDLA PROTI VYMEJŠLENÍ (ANTI-HALLUCINATION):
1. NIKDY SI NEVYMÝŠLEJ texty, slovíčka ani pravidla, která v této lekci nejsou! Máš výše doslovný obsah.
2. Pokud student zmíní nějaké cvičení nebo větu z tištěné knihy, kterou v datech nevidíš, KLIDNĚ SE HO ZEPTEJ: "Přečti mi prosím, co přesně máš na té stránce napsané, a podíváme se na to spolu."
3. NIKDY se neptej na obecný small talk (jak se má, jaké je počasí apod.). Celá hodina se točí POUZE kolem této lekce na ${bookMeta.pages}!
4. VYSVĚTLOVÁNÍ A NAVIGACE: Mluv VÝHRADNĚ v ${langLabel}. Španělsky mluv jen při předčítání vět z knihy nebo zkoušení výslovnosti.
5. FILTROVÁNÍ: Pokud student chce vyplňovat nudná písemná cvičení, řekni mu: "To přeskoč, je to ztráta času. Raději si pojďme zkusit tuto větu z dialogu říct nahlas."

JAK ZAHÁJIT HOVOR:
Ihned po připojení začni v ${langLabel} energicky a přesně takto:
"Ahoj ${userName}! Mám před sebou otevřenou Lekci ${bookMeta.lessonNumber}: ${bookMeta.title} na ${bookMeta.pages}. Máš knížku před sebou? Na co se podíváme nejdřív – na úvodní dialog, nebo si projdeme gramatiku?"
`;

  const startSession = useCallback(async () => {
    if (!apiKey) { setErrorMsg('Chybí NEXT_PUBLIC_GEMINI_API_KEY'); return; }
    soundEngine.playTick();
    setMessages([]);
    setErrorMsg(null);

    const session = new LiveTutorSession(apiKey, {
      onStatusChange: setStatus,
      onTranscript: handleTranscript,
      onError: setErrorMsg,
    });
    sessionRef.current = session;

    await session.connect({
      mode: '__textbook_lesson__',
      topic: `Lekce ${bookMeta.lessonNumber}: ${bookMeta.title}`,
      nativeLanguage: language as any,
      level: 'A1',
      voiceId,
      situation: textbookSystemPrompt,
      userName,
    });
  }, [apiKey, language, bookMeta, handleTranscript, textbookSystemPrompt, voiceId, userName]);

  const stopSession = useCallback(async () => {
    soundEngine.playUntick();
    await sessionRef.current?.disconnect();
    sessionRef.current = null;
    setStatus('idle');
  }, []);

  const sendQuickPrompt = (promptText: string) => {
    soundEngine.playTick();
    sessionRef.current?.sendTextMessage(promptText);
    handleTranscript('user', `💬 (${promptText})`);
  };

  const isActive = status === 'listening' || status === 'speaking';
  const statusCfg = STATUS_CONFIG[status];

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center p-2 sm:p-4 bg-black/75 backdrop-blur-xl animate-fade-in overflow-y-auto">
      <div className="relative w-full max-w-2xl apple-glass bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] rounded-3xl shadow-2xl flex flex-col my-auto max-h-[96vh] sm:max-h-[90vh] overflow-hidden animate-scale-in">

        {/* Header */}
        <div className="flex items-center justify-between p-3.5 sm:p-5 border-b border-[var(--card-border)] bg-[var(--card-bg-hover)] shrink-0">
          <div className="min-w-0">
            <div className="flex items-center gap-2">
              <div className={`w-2.5 h-2.5 rounded-full ${
                status === 'listening' ? 'bg-rose-400 animate-pulse' :
                status === 'speaking'  ? 'bg-cyan-400 animate-pulse' :
                status === 'connecting'? 'bg-amber-400 animate-pulse' :
                status === 'ready'     ? 'bg-emerald-400' : 'bg-gray-400'
              }`} />
              <h2 className="font-black text-[var(--text-primary)] text-sm sm:text-base truncate">
                📖 Lektorka pro Lekci {bookMeta.lessonNumber}: {bookMeta.title}
              </h2>
            </div>
            <p className={`text-[11px] sm:text-xs mt-0.5 font-mono ${statusCfg.color} ${statusCfg.pulse ? 'animate-pulse' : ''}`}>
              {statusCfg.label} • {bookMeta.pages}
            </p>
          </div>

          <button
            onClick={() => { stopSession(); onClose(); }}
            className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] text-2xl leading-none cursor-pointer transition px-2 py-1"
          >
            ×
          </button>
        </div>

        {/* Body Container */}
        <div className="flex-1 overflow-y-auto space-y-3 p-3.5 sm:p-5 custom-scrollbar">

          {/* Visual Orb */}
          <div className="flex justify-center py-1 relative">
            <div className={`relative flex items-center justify-center w-20 h-20 sm:w-24 sm:h-24 rounded-full transition-all duration-500 ${
              status === 'listening'
                ? 'bg-rose-500/15 shadow-[0_0_50px_rgba(244,63,94,0.5)]'
                : status === 'speaking'
                ? 'bg-cyan-500/15 shadow-[0_0_50px_rgba(6,182,212,0.5)]'
                : 'bg-[var(--card-bg-hover)] border border-[var(--card-border)]'
            }`}>
              {isActive && (
                <>
                  <div className={`absolute inset-0 rounded-full border-2 animate-ping opacity-30 ${status === 'listening' ? 'border-rose-400' : 'border-cyan-400'}`} />
                  <div className={`absolute inset-[-6px] rounded-full border animate-pulse opacity-20 ${status === 'listening' ? 'border-rose-300' : 'border-cyan-300'}`} />
                </>
              )}
              <div className="text-3xl select-none">
                {status === 'listening'  ? '🎙️' :
                 status === 'speaking'   ? '🔊' :
                 status === 'connecting' ? '⏳' :
                 status === 'error'      ? '⚠️' : '👩‍🏫'}
              </div>
            </div>
          </div>

          {/* Info Badge before start */}
          {status === 'idle' && (
            <div className="p-3.5 rounded-2xl bg-[var(--accent-amber)]/10 border border-[var(--accent-amber)]/30 text-xs space-y-1 text-[var(--text-primary)]">
              <p className="font-bold text-[var(--accent-amber)]">📚 Společné čtení Lekce {bookMeta.lessonNumber}:</p>
              <p>• Otevři si knížku na <strong className="text-[var(--text-primary)]">{bookMeta.pages}</strong>.</p>
              <p>• Lektorka má před sebou doslovný text dialogů i slovíčka a přesně ví, co probíráte.</p>
            </div>
          )}

          {/* Transcript Log */}
          <div ref={scrollRef} className="space-y-2.5 min-h-[110px] max-h-[220px] overflow-y-auto p-3 bg-[var(--card-bg-hover)] rounded-2xl border border-[var(--card-border)]">
            {messages.length === 0 && status === 'connecting' && (
              <div className="text-center py-4 text-amber-400 text-xs animate-pulse font-mono">
                Připojuji lektorku k Lekci {bookMeta.lessonNumber}...
              </div>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex gap-2 animate-fade-up ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className="text-base shrink-0 mt-0.5">{m.role === 'user' ? '🧑‍🎓' : '👩‍🏫'}</div>
                <div className={`px-3 py-2 rounded-2xl text-xs sm:text-sm leading-relaxed max-w-[85%] ${
                  m.role === 'user'
                    ? 'bg-emerald-500/20 border border-emerald-500/40 text-[var(--text-primary)]'
                    : 'bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)]'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
          </div>

          {/* Rychlá interaktivní tlačítka */}
          {isActive && (
            <div className="space-y-1.5 pt-1">
              <span className="text-[10px] font-mono uppercase tracking-wider text-[var(--text-muted)] block text-center">
                Klikni a zeptej se lektorky:
              </span>
              <div className="flex flex-wrap gap-1.5 justify-center">
                <button
                  type="button"
                  onClick={() => sendQuickPrompt(`Pojďme si projít úvodní dialog na straně ${bookMeta.pages}. Přečti první větu a zkontroluj mou výslovnost.`)}
                  className="px-3 py-1.5 rounded-xl bg-cyan-500/15 hover:bg-cyan-500/25 border border-cyan-500/30 text-cyan-700 dark:text-cyan-300 text-xs font-bold transition cursor-pointer"
                >
                  📖 Projít dialog
                </button>
                <button
                  type="button"
                  onClick={() => sendQuickPrompt(`Vysvětli mi prosím stručně gramatiku této lekce (${bookMeta.grammarTopics[0] || 'gramatiku'}).`)}
                  className="px-3 py-1.5 rounded-xl bg-amber-500/15 hover:bg-amber-500/25 border border-amber-500/30 text-amber-800 dark:text-amber-300 text-xs font-bold transition cursor-pointer"
                >
                  💡 Vysvětlit gramatiku
                </button>
                <button
                  type="button"
                  onClick={() => sendQuickPrompt(`Která cvičení na straně ${bookMeta.pages} mám přeskočit a co si raději procvičit?`)}
                  className="px-3 py-1.5 rounded-xl bg-rose-500/15 hover:bg-rose-500/25 border border-rose-500/30 text-rose-800 dark:text-rose-300 text-xs font-bold transition cursor-pointer"
                >
                  ⛔ Co přeskočit?
                </button>
                <button
                  type="button"
                  onClick={() => sendQuickPrompt(`Vyzkoušej mě ze 2 vět z dialogu této lekce a nech mě odpovědět španělsky.`)}
                  className="px-3 py-1.5 rounded-xl bg-emerald-500/15 hover:bg-emerald-500/25 border border-emerald-500/30 text-emerald-800 dark:text-emerald-300 text-xs font-bold transition cursor-pointer"
                >
                  🎯 Vyzkoušej mě
                </button>
              </div>
            </div>
          )}

          {errorMsg && (
            <div className="px-3 py-2 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs font-mono">
              ⚠️ {errorMsg}
            </div>
          )}
        </div>

        {/* Controls Footer */}
        <div className="p-3.5 sm:p-5 border-t border-[var(--card-border)] bg-[var(--card-bg-hover)] space-y-2.5 shrink-0">
          {!isActive && status !== 'connecting' && (
            <div className="flex items-center gap-1.5 flex-wrap justify-center">
              <span className="text-[11px] text-[var(--text-secondary)] font-mono">{t.voiceLabel}</span>
              {LIVE_VOICES.map((v) => (
                <button
                  key={v.id}
                  onClick={() => {
                    soundEngine.playTick();
                    setVoiceId(v.id);
                  }}
                  className={`px-2.5 py-1 rounded-xl text-[11px] font-bold border transition cursor-pointer ${
                    voiceId === v.id
                      ? 'bg-[var(--accent-blue)] text-white border-[var(--accent-blue)]'
                      : 'bg-[var(--card-bg)] border-[var(--card-border)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                  }`}
                >
                  {v.id} ({v.gender === 'female' ? t.voiceFemale : t.voiceMale})
                </button>
              ))}
            </div>
          )}

          <div className="flex gap-2 justify-center">
            {status === 'idle' || status === 'closed' || status === 'error' ? (
              <button
                onClick={startSession}
                disabled={!apiKey}
                className="w-full sm:w-auto px-7 py-3 rounded-2xl bg-emerald-500 hover:bg-emerald-400 font-black text-slate-950 text-xs sm:text-sm transition cursor-pointer shadow-lg hover:scale-105 active:scale-95 disabled:opacity-40"
              >
                ▶ Spustit hodinu k Lekci {bookMeta.lessonNumber}
              </button>
            ) : (
              <button
                onClick={stopSession}
                className="w-full sm:w-auto px-7 py-3 rounded-2xl bg-rose-600 hover:bg-rose-500 font-black text-white text-xs sm:text-sm transition cursor-pointer shadow-lg hover:scale-105 active:scale-95"
              >
                ⏹ Ukončit hodinu
              </button>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

'use client';

import { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { BookLessonDetail } from '@/lib/data/book-curriculum';
import { getProkopovaLessonData } from '@/lib/data/prokopova-book-data';
import { useAppLanguage } from '@/lib/context/LanguageContext';
import { getTranslation } from '@/lib/translations';
import { soundEngine } from '@/lib/audio/sound-engine';
import { ttsEngine } from '@/lib/audio/tts';
import TextbookLiveModal from '@/components/TextbookLiveModal';

interface TextbookModalProps {
  isOpen: boolean;
  onClose: () => void;
  dayNumber: number;
  bookMeta: BookLessonDetail;
  userName?: string;
  userId?: string;
}

type TabType = 'dialogues' | 'grammar' | 'vocab' | 'exercises';

// Formátování času MM:SS
const formatTime = (timeInSeconds: number) => {
  if (isNaN(timeInSeconds) || timeInSeconds < 0) return '00:00';
  const minutes = Math.floor(timeInSeconds / 60);
  const seconds = Math.floor(timeInSeconds % 60);
  return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
};

// Pomocná funkce pro bezpečné vytažení textu položky cvičení z libovolného formátu v JSONu
const getItemText = (item: any): string => {
  if (!item) return '';
  if (typeof item === 'string') return item;
  return (
    item.sentence ||
    item.prompt ||
    item.text ||
    item.q ||
    item.question ||
    item.statement ||
    item.original ||
    item.present ||
    item.fact ||
    item.action ||
    item.phrase ||
    item.masculine ||
    item.feminine ||
    item.direct ||
    item.habitual ||
    item.item ||
    ''
  );
};

export default function TextbookModal({
  isOpen,
  onClose,
  dayNumber,
  bookMeta,
  userName = 'Karel',
  userId,
}: TextbookModalProps) {
  const { language } = useAppLanguage();
  const t = getTranslation(language);

  // Tab State
  const [activeTab, setActiveTab] = useState<TabType>('dialogues');

  // Načtení dat z JSONu podle čísla lekce
  const rawLesson = useMemo(
    () => getProkopovaLessonData(bookMeta.lessonNumber) as any,
    [bookMeta.lessonNumber]
  );

  // Převod ID stopy (oddil_1_track_07) na reálný soubor (1_07.mp3)
  const resolveAudioFile = (trackId: string) => {
    const match1 = trackId?.match(/oddil_1_track_(\d+)/);
    if (match1) return `1_${match1[1].padStart(2, '0')}.mp3`;
    const match2 = trackId?.match(/oddil_2_track_(\d+)/);
    if (match2) return `2_${match2[1].padStart(2, '0')}.mp3`;
    return trackId?.endsWith('.mp3') ? trackId : `${trackId}.mp3`;
  };

  // Seznam stop pro přehrávač
  const tracksList = useMemo(() => {
    if (rawLesson?.audio_tracks && Array.isArray(rawLesson.audio_tracks) && rawLesson.audio_tracks.length > 0) {
      return rawLesson.audio_tracks.map((tItem: any) => ({
        file: resolveAudioFile(tItem.id || tItem.track || ''),
        code: tItem.code || tItem.name || '',
        description: tItem.description || tItem.type || '',
      }));
    }
    return (bookMeta.audioTracks || []).map((tItem) => ({
      file: tItem.file,
      code: tItem.label,
      description: tItem.label,
    }));
  }, [rawLesson, bookMeta]);

  // Audio Player State
  const [activeTrackFile, setActiveTrackFile] = useState<string | null>(tracksList[0]?.file || null);
  const [activeTrackDesc, setActiveTrackDesc] = useState<string>(tracksList[0]?.description || '');
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playbackRate, setPlaybackRate] = useState<number>(1.0);
  const [isLooping, setIsLooping] = useState(false);

  // Další stavy
  const [vocabSearch, setVocabSearch] = useState('');
  const [revealedExercises, setRevealedExercises] = useState<Set<number>>(new Set());
  const [userAnswers, setUserAnswers] = useState<{ [key: string]: string }>({});
  const [copiedSentence, setCopiedSentence] = useState<string | null>(null);
  const [isLiveTutorOpen, setIsLiveTutorOpen] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Bezpečné zastavení přehrávání
  const stopAudio = useCallback(() => {
    if (audioRef.current) {
      audioRef.current.pause();
    }
    setIsPlayingAudio(false);
  }, []);

  // Reset a vyčištění při změně lekce
  useEffect(() => {
    if (tracksList.length > 0) {
      setActiveTrackFile(tracksList[0].file);
      setActiveTrackDesc(tracksList[0].description || tracksList[0].code);
    }
    setCurrentTime(0);
    stopAudio();
    setVocabSearch('');
    setRevealedExercises(new Set());
    setUserAnswers({});
  }, [bookMeta.lessonNumber, tracksList, stopAudio]);

  // Vyčištění při unmountu
  useEffect(() => {
    return () => {
      stopAudio();
    };
  }, [stopAudio]);

  // Bezpečné volání TTS (zastaví MP3 a ověří neprázdnost textu)
  const handleSpeak = (text?: string | null) => {
    if (!text || typeof text !== 'string' || !text.trim()) return;
    if (isPlayingAudio) stopAudio();
    ttsEngine.speak(text.trim());
  };

  const handleSelectTrack = (trackFile: string, description: string) => {
    soundEngine.playTick();
    if (activeTrackFile === trackFile && isPlayingAudio) {
      stopAudio();
      return;
    }

    setActiveTrackFile(trackFile);
    setActiveTrackDesc(description);
    setIsPlayingAudio(true);

    if (audioRef.current) {
      // Load MP3 from GitHub CDN
      audioRef.current.src = `https://raw.githubusercontent.com/Kajakundak/espanol-90/main/public/mp3/${trackFile}`;
      audioRef.current.playbackRate = playbackRate;
      audioRef.current.loop = isLooping;
      audioRef.current.play().catch(console.warn);
    }
  };

  const togglePlayPause = () => {
    soundEngine.playTick();
    if (!audioRef.current) return;

    if (isPlayingAudio) {
      stopAudio();
    } else {
      if (!audioRef.current.src && tracksList[0]) {
        handleSelectTrack(tracksList[0].file, tracksList[0].description);
        return;
      }
      audioRef.current.play().catch(console.warn);
      setIsPlayingAudio(true);
    }
  };

  const skipSeconds = (seconds: number) => {
    soundEngine.playTick();
    if (!audioRef.current) return;
    const newTime = Math.max(0, Math.min(duration, audioRef.current.currentTime + seconds));
    audioRef.current.currentTime = newTime;
    setCurrentTime(newTime);
  };

  const cyclePlaybackRate = () => {
    soundEngine.playTick();
    const rates = [0.8, 1.0, 1.2];
    const nextRate = rates[(rates.indexOf(playbackRate) + 1) % rates.length];
    setPlaybackRate(nextRate);
    if (audioRef.current) audioRef.current.playbackRate = nextRate;
  };

  const toggleLoop = () => {
    soundEngine.playTick();
    const next = !isLooping;
    setIsLooping(next);
    if (audioRef.current) audioRef.current.loop = next;
  };

  // Klávesové zkratky (Mezerník = Play/Pause, Šipky = skok, 1-4 = taby, Esc = zavřít)
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (e.code === 'Space') {
        e.preventDefault();
        togglePlayPause();
      } else if (e.code === 'ArrowLeft') {
        e.preventDefault();
        skipSeconds(-5);
      } else if (e.code === 'ArrowRight') {
        e.preventDefault();
        skipSeconds(5);
      } else if (e.key === '1') setActiveTab('dialogues');
      else if (e.key === '2') setActiveTab('grammar');
      else if (e.key === '3') setActiveTab('vocab');
      else if (e.key === '4') setActiveTab('exercises');
      else if (e.key === 'Escape') {
        stopAudio();
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, isPlayingAudio, duration, onClose, stopAudio]);

  const toggleExerciseReveal = (exNum: number) => {
    soundEngine.playTick();
    setRevealedExercises((prev) => {
      const next = new Set(prev);
      if (next.has(exNum)) next.delete(exNum);
      else next.add(exNum);
      return next;
    });
  };

  const handleCopySentence = (text: string) => {
    soundEngine.playTick();
    navigator.clipboard.writeText(text);
    setCopiedSentence(text);
    setTimeout(() => setCopiedSentence(null), 2000);
  };

  const filteredVocabulary = (rawLesson?.vocabulary || []).filter((w: any) => {
    if (!vocabSearch.trim()) return true;
    const q = vocabSearch.toLowerCase();
    return w.word?.toLowerCase().includes(q) || w.translation?.toLowerCase().includes(q);
  });

  const pageRange = rawLesson?.pages?.book_new_edition
    ? `str. ${rawLesson.pages.book_new_edition.start}–${rawLesson.pages.book_new_edition.end}`
    : bookMeta.pages;

  if (!isOpen) return null;

  return (
    <>
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-2 sm:p-4 bg-black/80 backdrop-blur-xl animate-fade-in overflow-hidden">
        <div className="relative w-full max-w-4xl h-[96vh] sm:h-[92vh] bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)] rounded-3xl shadow-2xl backdrop-blur-2xl flex flex-col overflow-hidden animate-scale-in">
          
          {/* ── 1. HORNÍ LIŠTA ── */}
          <div className="flex items-center justify-between border-b border-[var(--card-border)] px-5 sm:px-7 py-3.5 bg-[var(--card-bg-hover)] shrink-0 gap-3">
            <div className="flex items-center space-x-3 min-w-0">
              <span className="text-2xl shrink-0">📖</span>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[var(--accent-amber)] font-mono">
                    Lekce {rawLesson?.lesson_number || bookMeta.lessonNumber}
                  </span>
                  <span className="text-[10px] font-mono text-[var(--text-muted)]">
                    {pageRange}
                  </span>
                </div>
                <h2 className="text-sm sm:text-base font-extrabold text-[var(--text-primary)] truncate">
                  {rawLesson?.title_es || bookMeta.title}
                  <span className="text-xs font-normal text-[var(--text-secondary)] ml-2 hidden sm:inline">
                    ({rawLesson?.title_cs || bookMeta.spanishTitle})
                  </span>
                </h2>
              </div>
            </div>

            <div className="flex items-center gap-2 shrink-0">
              <button
                type="button"
                onClick={() => {
                  soundEngine.playTick();
                  stopAudio();
                  setIsLiveTutorOpen(true);
                }}
                className="px-3.5 py-1.5 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-black text-xs transition cursor-pointer shadow-md flex items-center gap-1.5 hover:scale-105 active:scale-95"
              >
                <span>🎙️</span>
                <span className="hidden sm:inline">Probrat s AI</span>
              </button>

              <button
                type="button"
                onClick={() => {
                  soundEngine.playUntick();
                  stopAudio();
                  onClose();
                }}
                className="w-8 h-8 rounded-full bg-[var(--card-bg)] border border-[var(--card-border)] text-sm font-bold text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--card-bg-hover)] transition flex items-center justify-center cursor-pointer"
              >
                ✕
              </button>
            </div>
          </div>

          {/* ── 2. AUDIO PŘEHRÁVAČ ── */}
          {tracksList.length > 0 && (
            <div className="px-3 sm:px-5 py-2 sm:py-3 bg-[var(--card-bg)] border-b border-[var(--card-border)] shrink-0 space-y-2 overflow-x-auto">
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2 sm:gap-3">
                <div className="flex items-center gap-2.5 min-w-0 w-full sm:w-auto">
                  <button
                    type="button"
                    onClick={togglePlayPause}
                    className={`min-h-[44px] min-w-[44px] sm:min-h-auto sm:min-w-auto w-10 h-10 sm:w-9 sm:h-9 rounded-xl font-bold text-xs flex items-center justify-center transition cursor-pointer shrink-0 shadow-sm ${
                      isPlayingAudio ? 'bg-[var(--accent-amber)] text-black' : 'bg-[var(--accent-cyan)] text-black'
                    }`}
                  >
                    {isPlayingAudio ? '⏸' : '▶'}
                  </button>
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-extrabold text-[var(--text-primary)] truncate">
                      {activeTrackDesc || activeTrackFile}
                    </p>
                    <span className="text-[10px] font-mono text-[var(--accent-cyan)] font-bold hidden sm:block">
                      {activeTrackFile}
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-1 sm:gap-2 shrink-0 w-full sm:w-auto overflow-x-auto pb-1 sm:pb-0">
                  <button
                    type="button"
                    onClick={() => skipSeconds(-5)}
                    className="p-1.5 px-1.5 sm:px-2 rounded-lg bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[9px] sm:text-[10px] font-bold text-[var(--text-secondary)] hover:text-[var(--text-primary)] cursor-pointer whitespace-nowrap"
                    title="Zpět o 5 sekund (Šipka vlevo)"
                  >
                    <span className="hidden sm:inline">⏪ -5s</span>
                    <span className="sm:hidden">⏪</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => skipSeconds(5)}
                    className="p-1.5 px-1.5 sm:px-2 rounded-lg bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[9px] sm:text-[10px] font-bold text-[var(--text-secondary)] hover:text-[var(--text-primary)] cursor-pointer whitespace-nowrap"
                    title="Vpřed o 5 sekund (Šipka vpravo)"
                  >
                    <span className="hidden sm:inline">+5s ⏩</span>
                    <span className="sm:hidden">⏩</span>
                  </button>
                  <button
                    type="button"
                    onClick={cyclePlaybackRate}
                    className="p-1.5 px-1.5 sm:px-2 rounded-lg bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-[9px] sm:text-[10px] font-mono font-bold text-[var(--accent-cyan)] cursor-pointer whitespace-nowrap"
                    title="Playback rate"
                  >
                    {playbackRate.toFixed(1)}×
                  </button>
                  <button
                    type="button"
                    onClick={toggleLoop}
                    className={`p-1.5 rounded-lg border text-[10px] font-bold cursor-pointer shrink-0 ${
                      isLooping ? 'bg-[var(--accent-cyan)]/20 border-[var(--accent-cyan)] text-[var(--accent-cyan)]' : 'border-[var(--card-border)] text-[var(--text-secondary)]'
                    }`}
                    title="Opakovat stopu ve smyčce"
                  >
                    🔁
                  </button>
                  <span className="text-[9px] sm:text-[10px] font-mono text-[var(--text-secondary)] font-bold pl-0 sm:pl-1 whitespace-nowrap">
                    {formatTime(currentTime)} / {formatTime(duration)}
                  </span>
                </div>
              </div>

              <input
                type="range"
                min="0"
                max={duration || 100}
                step="0.1"
                value={currentTime}
                onChange={(e) => {
                  const newTime = parseFloat(e.target.value);
                  setCurrentTime(newTime);
                  if (audioRef.current) audioRef.current.currentTime = newTime;
                }}
                className="w-full h-1.5 bg-[var(--card-border)] rounded-lg appearance-none cursor-pointer accent-[var(--accent-cyan)] transition touch-manipulation"
              />

              <div className="flex items-center gap-1 sm:gap-1.5 overflow-x-auto pb-1 scrollbar-none pt-0.5">
                {tracksList.map((tItem: any, idx: number) => {
                  const isSel = activeTrackFile === tItem.file;
                  return (
                    <button
                      key={idx}
                      type="button"
                      onClick={() => handleSelectTrack(tItem.file, tItem.description)}
                      className={`px-2 sm:px-2.5 py-1 rounded-lg text-[9px] sm:text-[10px] font-mono font-bold whitespace-nowrap transition cursor-pointer border shrink-0 min-h-[36px] sm:min-h-auto flex items-center justify-center ${
                        isSel
                          ? 'bg-[var(--accent-cyan)]/20 border-[var(--accent-cyan)] text-[var(--accent-cyan)]'
                          : 'bg-[var(--card-bg-hover)] border-[var(--card-border)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                      }`}
                    >
                      <span>{isSel && isPlayingAudio ? '🔊' : '▶'}</span> <span className="hidden sm:inline">{tItem.code}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* ── 3. NAVIGAČNÍ ZÁLOŽKY ── */}
          <div className="flex items-center gap-2 px-5 py-2.5 border-b border-[var(--card-border)] bg-[var(--card-bg-hover)] shrink-0 overflow-x-auto">
            <button
              onClick={() => { soundEngine.playTick(); setActiveTab('dialogues'); }}
              className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition whitespace-nowrap cursor-pointer flex items-center gap-1.5 ${
                activeTab === 'dialogues'
                  ? 'bg-[var(--accent-cyan)]/20 border border-[var(--accent-cyan)] text-[var(--accent-cyan)] font-extrabold shadow-sm'
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
              }`}
            >
              <span>💬</span> Texty & Dialogy [1]
            </button>

            <button
              onClick={() => { soundEngine.playTick(); setActiveTab('grammar'); }}
              className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition whitespace-nowrap cursor-pointer flex items-center gap-1.5 ${
                activeTab === 'grammar'
                  ? 'bg-[var(--accent-cyan)]/20 border border-[var(--accent-cyan)] text-[var(--accent-cyan)] font-extrabold shadow-sm'
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
              }`}
            >
              <span>💡</span> Gramatika [2]
            </button>

            <button
              onClick={() => { soundEngine.playTick(); setActiveTab('vocab'); }}
              className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition whitespace-nowrap cursor-pointer flex items-center gap-1.5 ${
                activeTab === 'vocab'
                  ? 'bg-[var(--accent-cyan)]/20 border border-[var(--accent-cyan)] text-[var(--accent-cyan)] font-extrabold shadow-sm'
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
              }`}
            >
              <span>📚</span> Slovníček ({rawLesson?.vocabulary?.length || 0}) [3]
            </button>

            <button
              onClick={() => { soundEngine.playTick(); setActiveTab('exercises'); }}
              className={`px-3.5 py-1.5 rounded-xl text-xs font-bold transition whitespace-nowrap cursor-pointer flex items-center gap-1.5 ${
                activeTab === 'exercises'
                  ? 'bg-[var(--accent-cyan)]/20 border border-[var(--accent-cyan)] text-[var(--accent-cyan)] font-extrabold shadow-sm'
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
              }`}
            >
              <span>🎯</span> Cvičení ({rawLesson?.exercises?.length || 0}) [4]
            </button>
          </div>

          {/* ── 4. TĚLO ZÁLOŽKY ── */}
          <div className="flex-1 overflow-y-auto p-5 sm:p-7 space-y-6 custom-scrollbar text-xs sm:text-sm">
            
            {/* 💬 TAB 1: TEXTY & DIALOGY */}
            {activeTab === 'dialogues' && (
              <div className="space-y-6">
                {rawLesson?.texts && rawLesson.texts.length > 0 ? (
                  rawLesson.texts.map((sec: any, secIdx: number) => (
                    <div key={secIdx} className="p-5 rounded-2xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] space-y-4">
                      {sec.section_title && (
                        <div className="flex items-center justify-between border-b border-[var(--card-border)] pb-2">
                          <h3 className="font-extrabold text-sm text-[var(--accent-cyan)] flex items-center gap-2">
                            <span>📄</span> {sec.section_title}
                          </h3>
                          {sec.author && (
                            <span className="text-[11px] font-mono text-[var(--accent-amber)]">
                              {sec.author}
                            </span>
                          )}
                        </div>
                      )}

                      {/* Odstavce */}
                      {sec.paragraphs && Array.isArray(sec.paragraphs) && (
                        <div className="space-y-3">
                          {sec.paragraphs.map((p: any, pIdx: number) => {
                            const pText = p.text || p.content;
                            return (
                              <div key={pIdx} className="p-3.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] space-y-2">
                                {p.title && <h4 className="text-xs font-bold text-[var(--accent-amber)]">{p.title}</h4>}
                                {pText && (
                                  <div className="flex items-start justify-between gap-3">
                                    <p className="text-sm font-medium text-[var(--text-primary)] leading-relaxed">
                                      {pText}
                                    </p>
                                    <button
                                      type="button"
                                      onClick={() => handleSpeak(pText)}
                                      className="p-1.5 rounded-lg bg-[var(--card-bg-hover)] hover:bg-white/10 text-[var(--text-secondary)] hover:text-[var(--text-primary)] border border-[var(--card-border)] text-xs shrink-0 cursor-pointer"
                                    >
                                      🔊
                                    </button>
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      )}

                      {/* Repliky v dialogu */}
                      {sec.lines && Array.isArray(sec.lines) && (
                        <div className="space-y-2.5">
                          {sec.lines.map((line: any, lIdx: number) => (
                            <div
                              key={lIdx}
                              className="p-3 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] hover:border-[var(--accent-cyan)]/40 transition flex items-start justify-between gap-3"
                            >
                              <div className="space-y-1 flex-1">
                                {line.speaker && (
                                  <span className="text-[11px] font-bold uppercase tracking-wider text-[var(--accent-amber)] font-mono block">
                                    {line.speaker}:
                                  </span>
                                )}
                                <p className="text-sm font-bold text-[var(--text-primary)] leading-relaxed">
                                  {line.text}
                                </p>
                              </div>

                              <div className="flex items-center gap-1.5 shrink-0 pt-0.5">
                                <button
                                  type="button"
                                  onClick={() => handleSpeak(line.text)}
                                  className="p-1.5 rounded-lg bg-[var(--card-bg-hover)] hover:bg-white/10 text-[var(--text-secondary)] hover:text-[var(--text-primary)] border border-[var(--card-border)] text-xs cursor-pointer"
                                  title="Poslech"
                                >
                                  🔊
                                </button>
                                <button
                                  type="button"
                                  onClick={() => handleCopySentence(line.text)}
                                  className="p-1.5 px-2 rounded-lg bg-[var(--card-bg-hover)] hover:bg-emerald-500/20 text-[var(--text-secondary)] hover:text-emerald-400 border border-[var(--card-border)] text-[10px] font-bold font-mono cursor-pointer"
                                  title="Zkopírovat pro Anki"
                                >
                                  {copiedSentence === line.text ? '✓' : '+ Anki'}
                                </button>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}

                      {/* Scény */}
                      {sec.scenes && Array.isArray(sec.scenes) && (
                        <div className="space-y-4">
                          {sec.scenes.map((scene: any, sIdx: number) => (
                            <div key={sIdx} className="p-4 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] space-y-3">
                              {scene.title && (
                                <h4 className="text-xs font-black uppercase tracking-wider text-[var(--accent-cyan)] font-mono border-b border-[var(--card-border)] pb-1.5">
                                  {scene.title}
                                </h4>
                              )}
                              <div className="space-y-2">
                                {scene.lines?.map((sLine: any, slIdx: number) => (
                                  <div key={slIdx} className="text-xs flex items-start justify-between gap-2">
                                    <div>
                                      {sLine.speaker && <strong className="text-[var(--accent-amber)] font-mono mr-1.5">{sLine.speaker}:</strong>}
                                      <span className="font-semibold text-[var(--text-primary)]">{sLine.text}</span>
                                    </div>
                                    <button
                                      type="button"
                                      onClick={() => handleSpeak(sLine.text)}
                                      className="text-xs text-[var(--text-muted)] hover:text-white shrink-0 cursor-pointer"
                                    >
                                      🔊
                                    </button>
                                  </div>
                                ))}
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  ))
                ) : (
                  <div className="p-6 text-center text-xs text-[var(--text-muted)] bg-[var(--card-bg-hover)] rounded-2xl">
                    Text lekce načten z knihy.
                  </div>
                )}

                {/* Poznámky k lekci */}
                {rawLesson?.cultural_and_linguistic_notes && rawLesson.cultural_and_linguistic_notes.length > 0 && (
                  <div className="p-5 rounded-2xl bg-[var(--accent-amber)]/10 border border-[var(--accent-amber)]/30 space-y-3">
                    <h4 className="font-extrabold text-xs uppercase tracking-wider text-[var(--accent-amber)] font-mono flex items-center gap-1.5">
                      <span>💡</span> Jazykové a kulturní poznámky:
                    </h4>
                    <div className="space-y-2">
                      {rawLesson.cultural_and_linguistic_notes.map((note: any) => (
                        <p key={note.id} className="text-xs text-[var(--text-primary)] leading-relaxed">
                          <strong className="text-[var(--accent-amber)]">[{note.id}] </strong>
                          {note.text}
                        </p>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* 💡 TAB 2: GRAMATIKA (OPRAVENO: UNIVERZÁLNÍ VYKRESLOVÁNÍ) */}
            {activeTab === 'grammar' && (
              <div className="space-y-4">
                {rawLesson?.grammar && rawLesson.grammar.length > 0 ? (
                  rawLesson.grammar.map((g: any, gIdx: number) => {
                    const c = g.content || {};

                    return (
                      <div key={gIdx} className="p-5 rounded-2xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] space-y-3">
                        <div className="flex items-center gap-2">
                          {g.roman_numeral && (
                            <span className="text-xs font-mono font-bold px-2.5 py-1 rounded-lg bg-[var(--accent-cyan)]/20 text-[var(--accent-cyan)]">
                              {g.roman_numeral}
                            </span>
                          )}
                          <h4 className="font-extrabold text-sm sm:text-base text-[var(--text-primary)]">
                            {g.title || g.topic_box || g.topic}
                          </h4>
                        </div>

                        {/* 1. Výklad / Definice / Jednotlivé pravidlo */}
                        {(c.rule || c.explanation || c.definition || g.explanation) && (
                          <p className="text-xs sm:text-sm font-semibold text-[var(--text-primary)] leading-relaxed bg-[var(--card-bg)] p-3 rounded-xl border border-[var(--card-border)]">
                            {c.rule || c.explanation || c.definition || g.explanation}
                          </p>
                        )}

                        {/* 2. Klasifikace samohlásek (Lekce 1 apod.) */}
                        {c.vowel_classification && (
                          <div className="grid grid-cols-2 gap-2">
                            <div className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs">
                              <span className="text-[10px] text-[var(--text-muted)] font-mono uppercase block">Silné samohlásky:</span>
                              <div className="flex gap-1.5 pt-1">
                                {c.vowel_classification.strong?.map((v: string, idx: number) => (
                                  <span key={idx} className="px-2 py-0.5 rounded bg-amber-500/20 text-amber-400 font-bold font-mono">{v}</span>
                                ))}
                              </div>
                            </div>
                            <div className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs">
                              <span className="text-[10px] text-[var(--text-muted)] font-mono uppercase block">Slabé samohlásky:</span>
                              <div className="flex gap-1.5 pt-1">
                                {c.vowel_classification.weak?.map((v: string, idx: number) => (
                                  <span key={idx} className="px-2 py-0.5 rounded bg-cyan-500/20 text-cyan-400 font-bold font-mono">{v}</span>
                                ))}
                              </div>
                            </div>
                          </div>
                        )}

                        {/* 3. Seznam pravidel v poli rules */}
                        {c.rules && Array.isArray(c.rules) && (
                          <div className="space-y-2">
                            {c.rules.map((rItem: any, rIdx: number) => (
                              <div key={rIdx} className="p-3 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] space-y-1.5">
                                {rItem.category && (
                                  <span className="text-[10px] font-bold uppercase tracking-wider text-[var(--accent-amber)] font-mono block">
                                    {rItem.category}
                                  </span>
                                )}
                                <p className="text-xs font-medium text-[var(--text-primary)] leading-relaxed">
                                  {typeof rItem === 'string' ? rItem : rItem.rule || rItem.explanation}
                                </p>
                                {rItem.examples && Array.isArray(rItem.examples) && (
                                  <div className="flex flex-wrap gap-1.5 pt-1">
                                    {rItem.examples.map((ex: any, exIdx: number) => (
                                      <span key={exIdx} className="px-2 py-0.5 rounded-md bg-[var(--accent-cyan)]/10 text-[var(--accent-cyan)] font-mono text-xs font-bold">
                                        {typeof ex === 'string'
                                          ? ex
                                          : `${ex.es || ex.word || ex.m || ''} ${ex.f ? '– ' + ex.f : ''} ${ex.cs || ex.meaning ? '(' + (ex.cs || ex.meaning) + ')' : ''}`}
                                      </span>
                                    ))}
                                  </div>
                                )}
                              </div>
                            ))}
                          </div>
                        )}

                        {/* 4. Příklady s překlady (c.examples) */}
                        {c.examples && Array.isArray(c.examples) && (
                          <div className="space-y-1.5 pt-1">
                            {c.examples.map((exItem: any, exIdx: number) => {
                              if (typeof exItem === 'string') {
                                return (
                                  <div key={exIdx} className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs font-bold text-[var(--accent-cyan)]">
                                    {exItem}
                                  </div>
                                );
                              }

                              const leftText = exItem.es || exItem.statement || exItem.affirmative || exItem.before || exItem.phrase || exItem.base || '';
                              const rightText = exItem.cs || exItem.statement_cs || exItem.affirmative_cs || exItem.cs_with || exItem.note || '';
                              const extraLeft = exItem.question || exItem.negative || exItem.after || '';
                              const extraRight = exItem.question_cs || exItem.negative_cs || '';

                              return (
                                <div key={exIdx} className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs flex flex-col gap-1">
                                  <div className="flex items-center justify-between gap-2">
                                    <span className="font-bold text-[var(--text-primary)]">{leftText}</span>
                                    {rightText && <span className="text-[var(--text-secondary)] italic">{rightText}</span>}
                                  </div>
                                  {extraLeft && (
                                    <div className="flex items-center justify-between gap-2 border-t border-[var(--card-border)] pt-1 text-[var(--accent-amber)]">
                                      <span className="font-bold font-mono">{extraLeft}</span>
                                      {extraRight && <span className="italic text-xs">{extraRight}</span>}
                                    </div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        )}

                        {/* 5. Kontrastní dvojice (pairs, contrast_examples) */}
                        {(c.pairs || c.contrast_examples) && Array.isArray(c.pairs || c.contrast_examples) && (
                          <div className="space-y-1.5 pt-1">
                            {(c.pairs || c.contrast_examples).map((pair: any, pIdx: number) => (
                              <div key={pIdx} className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs flex items-center justify-between gap-2">
                                <div className="space-y-0.5">
                                  <span className="font-bold text-[var(--accent-cyan)]">{pair.before || pair.present || pair.ser?.es}</span>
                                  <span className="text-[var(--text-muted)] mx-2">➔</span>
                                  <span className="font-bold text-[var(--accent-amber)]">{pair.after || pair.past || pair.estar?.es}</span>
                                </div>
                                <span className="text-[var(--text-secondary)] italic">{pair.cs || pair.ser?.cs || pair.estar?.cs}</span>
                              </div>
                            ))}
                          </div>
                        )}

                        {/* 6. Časování sloves */}
                        {c.conjugation && Array.isArray(c.conjugation) && (
                          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 pt-2">
                            {c.conjugation.map((cItem: any, cIdx: number) => (
                              <div key={cIdx} className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs">
                                <span className="text-[10px] text-[var(--text-muted)] font-mono block">{cItem.person}</span>
                                <strong className="text-[var(--accent-cyan)] font-bold text-sm">{cItem.form}</strong>
                                {cItem.cs && <span className="text-[11px] text-[var(--text-secondary)] block italic">{cItem.cs}</span>}
                              </div>
                            ))}
                          </div>
                        )}

                        {/* 7. Souhrnné tabulky */}
                        {g.summary_table && Array.isArray(g.summary_table) && (
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-1">
                            {g.summary_table.map((sItem: any, sIdx: number) => (
                              <div key={sIdx} className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs flex items-center justify-between">
                                <strong className="text-[var(--accent-cyan)]">{sItem.es}</strong>
                                <span className="text-[var(--text-secondary)] italic">{sItem.cs}</span>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    );
                  })
                ) : (
                  <div className="p-5 rounded-2xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] space-y-2">
                    <p className="text-xs text-[var(--text-secondary)]">{bookMeta.keyRuleTip}</p>
                  </div>
                )}
              </div>
            )}

            {/* 📚 TAB 3: SLOVNÍČEK */}
            {activeTab === 'vocab' && (
              <div className="space-y-4">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                  <div>
                    <h3 className="font-extrabold text-sm text-[var(--text-primary)]">
                      Slovní zásoba lekce ({rawLesson?.vocabulary?.length || 0} slov)
                    </h3>
                    <p className="text-[11px] text-[var(--text-secondary)]">Kliknutím na 🔊 si poslechneš výslovnost</p>
                  </div>

                  <input
                    type="text"
                    placeholder="Hledat slovo nebo překlad..."
                    value={vocabSearch}
                    onChange={(e) => setVocabSearch(e.target.value)}
                    className="px-3.5 py-1.5 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] text-xs text-[var(--text-primary)] outline-none focus:border-[var(--accent-cyan)] transition w-full sm:w-60"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                  {filteredVocabulary.map((w: any, idx: number) => (
                    <div
                      key={idx}
                      className="p-3 rounded-xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] flex items-center justify-between gap-2 hover:border-[var(--accent-cyan)]/40 transition"
                    >
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2">
                          <span className="font-extrabold text-sm text-[var(--text-primary)] truncate">
                            {w.word}
                          </span>
                          {w.gender && (
                            <span className="px-1.5 py-0.5 rounded text-[9px] font-mono font-bold bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-muted)]">
                              {w.gender}
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-[var(--text-secondary)] truncate">
                          {w.translation}
                        </p>
                        {w.notes && (
                          <p className="text-[10px] text-[var(--accent-amber)] italic truncate mt-0.5">
                            {w.notes}
                          </p>
                        )}
                      </div>

                      <button
                        type="button"
                        onClick={() => handleSpeak(w.word)}
                        className="p-1.5 rounded-lg bg-[var(--card-bg)] hover:bg-white/10 text-[var(--text-secondary)] hover:text-[var(--text-primary)] border border-[var(--card-border)] text-xs shrink-0 cursor-pointer"
                      >
                        🔊
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* 🎯 TAB 4: CVIČENÍ & INTERAKTIVITA */}
            {activeTab === 'exercises' && (
              <div className="space-y-4">
                <div className="p-4 rounded-2xl border-l-4 border-l-rose-500 bg-rose-500/10 border-y border-r border-rose-500/30 space-y-1 shadow-sm">
                  <div className="text-xs font-black text-[var(--accent-rose)] flex items-center gap-1.5 uppercase font-mono tracking-wider">
                    <span>⛔</span> Doporučení k lekci:
                  </div>
                  <p className="text-xs font-semibold text-[var(--text-primary)] leading-relaxed">
                    {bookMeta.whatToSkip}
                  </p>
                </div>

                {rawLesson?.exercises?.map((ex: any) => {
                  const isRevealed = revealedExercises.has(ex.number);
                  return (
                    <div
                      key={ex.number}
                      className="p-5 rounded-2xl bg-[var(--card-bg-hover)] border border-[var(--card-border)] space-y-3"
                    >
                      <div className="flex items-center justify-between gap-2">
                        <span className="font-mono font-black text-xs px-2.5 py-1 rounded-lg bg-[var(--card-bg)] border border-[var(--card-border)] text-[var(--text-primary)]">
                          Cvičení {ex.number}
                        </span>

                        {ex.has_key && (
                          <button
                            type="button"
                            onClick={() => toggleExerciseReveal(ex.number)}
                            className="px-3 py-1 rounded-lg bg-[var(--card-bg)] hover:bg-white/10 border border-[var(--card-border)] text-xs font-bold text-[var(--accent-cyan)] transition cursor-pointer"
                          >
                            {isRevealed ? 'Skrýt klíč' : '👁️ Zobrazit správné řešení'}
                          </button>
                        )}
                      </div>

                      <p className="text-xs sm:text-sm font-bold text-[var(--text-primary)] leading-relaxed">
                        {ex.title || ex.instruction}
                      </p>

                      {ex.sample && (
                        <div className="p-2.5 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs font-mono text-[var(--accent-amber)]">
                          {typeof ex.sample === 'string'
                            ? ex.sample
                            : `${ex.sample.prompt || ex.sample.question || ''} ➔ ${ex.sample.response || ex.sample.answer || ''}`}
                        </div>
                      )}

                      {/* Položky cvičení */}
                      {ex.items && Array.isArray(ex.items) && (
                        <div className="space-y-2 pt-1">
                          {ex.items.map((item: any, iIdx: number) => {
                            const itemText = getItemText(item);
                            const answerKey = `${ex.number}_${iIdx}`;
                            const isCorrect =
                              isRevealed &&
                              item.answer &&
                              userAnswers[answerKey]?.trim().toLowerCase() === item.answer.trim().toLowerCase();

                            return (
                              <div
                                key={iIdx}
                                className="p-3 rounded-xl bg-[var(--card-bg)] border border-[var(--card-border)] text-xs space-y-2"
                              >
                                <div className="flex items-center justify-between gap-2">
                                  <span className="font-medium text-[var(--text-primary)]">{itemText || '—'}</span>
                                  {itemText && (
                                    <button
                                      type="button"
                                      onClick={() => handleSpeak(itemText)}
                                      className="text-xs text-[var(--text-muted)] hover:text-white cursor-pointer"
                                      title="Přehrát"
                                    >
                                      🔊
                                    </button>
                                  )}
                                </div>

                                {item.answer && (
                                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 pt-1">
                                    <input
                                      type="text"
                                      placeholder="Napiš svou odpověď..."
                                      value={userAnswers[answerKey] || ''}
                                      onChange={(e) => setUserAnswers({ ...userAnswers, [answerKey]: e.target.value })}
                                      className={`px-3 py-1.5 rounded-lg bg-[var(--card-bg-hover)] border text-xs outline-none flex-1 transition ${
                                        isRevealed
                                          ? isCorrect
                                            ? 'border-emerald-500 text-emerald-400'
                                            : 'border-rose-500/50 text-rose-300'
                                          : 'border-[var(--card-border)] text-[var(--text-primary)]'
                                      }`}
                                    />
                                    {isRevealed && (
                                      <span className="font-mono font-bold text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded-lg border border-emerald-500/20 shrink-0 text-center">
                                        Klíč: {item.answer}
                                      </span>
                                    )}
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

          </div>

          {/* ── 5. SPODNÍ LIŠTA ── */}
          <div className="border-t border-[var(--card-border)] px-5 sm:px-7 py-3 bg-[var(--card-bg-hover)] flex items-center justify-between shrink-0">
            <span className="text-[11px] text-[var(--text-muted)] font-mono hidden sm:inline">
              {pageRange} • {bookMeta.title}
            </span>
            <button
              type="button"
              onClick={() => {
                soundEngine.playTick();
                stopAudio();
                onClose();
              }}
              className="px-6 py-2.5 rounded-full bg-amber-500 hover:bg-amber-400 text-slate-950 font-black text-xs transition cursor-pointer shadow-md hover:scale-105 active:scale-95 ml-auto sm:ml-0"
            >
              ✓ Zavřít čtečku [Esc]
            </button>
          </div>

        </div>
      </div>

      <audio
        ref={audioRef}
        onTimeUpdate={() => { if (audioRef.current) setCurrentTime(audioRef.current.currentTime); }}
        onLoadedMetadata={() => { if (audioRef.current) setDuration(audioRef.current.duration); }}
        onEnded={() => { if (!isLooping) setIsPlayingAudio(false); }}
        className="hidden"
      />

      {isLiveTutorOpen && (
        <TextbookLiveModal
          isOpen={isLiveTutorOpen}
          onClose={() => setIsLiveTutorOpen(false)}
          bookMeta={bookMeta}
          userName={userName}
          userId={userId}
        />
      )}
    </>
  );
}

'use client';

import { useVoiceInput } from '@/lib/audio/tts';
import { soundEngine } from '@/lib/audio/sound-engine';

interface VoiceButtonProps {
  onSpeechResult: (text: string) => void;
  disabled?: boolean;
}

export default function VoiceButton({ onSpeechResult, disabled }: VoiceButtonProps) {
  const { isListening, isSupported, error, startListening } = useVoiceInput((text) => {
    soundEngine.playTick();
    onSpeechResult(text);
  });

  const handleClick = () => {
    if (isListening) return;
    soundEngine.playTick();
    startListening();
  };

  if (!isSupported) {
    return null;
  }

  return (
    <div className="relative inline-block">
      {isListening && <div className="mic-ring" />}
      <button
        type="button"
        onClick={handleClick}
        disabled={disabled || isListening}
        className={`relative z-10 px-4 py-3 rounded-2xl font-bold text-xs transition cursor-pointer flex items-center gap-2 border ${
          isListening
            ? 'bg-rose-600 border-rose-400 text-white shadow-[0_0_20px_rgba(244,63,94,0.5)] animate-pulse'
            : 'bg-white/10 hover:bg-white/20 border-white/15 text-slate-200'
        }`}
        title="Mluv španělsky do mikrofonu (Web Speech API)"
      >
        <span className="text-base">{isListening ? '🔴' : '🎙️'}</span>
        <span className="hidden sm:inline font-mono">
          {isListening ? 'Poslouchám...' : 'Mluvit'}
        </span>
      </button>

      {error && (
        <div className="absolute bottom-full mb-2 left-0 right-0 whitespace-nowrap bg-rose-950 border border-rose-500/40 text-rose-200 text-[10px] px-2 py-1 rounded-md z-50">
          {error}
        </div>
      )}
    </div>
  );
}
